    /// `DO UPDATE SET <col> = <col> + ...` の構文（Issue #2425・SQL-49）。
    #[test]
    fn upsert_set_add_syntax_accepts_same_column_forms() {
        let lookup = catalog_with(&["documents"]);
        let lit = |s: &str| UpsertAddOperand::Literal(InsertLiteral::Number(s.to_string()));
        let cases: [(&str, UpsertAddOperand); 5] = [
            ("n = n + 1", lit("1")),
            ("n = n + -1", lit("-1")),
            ("n = n + +1", lit("+1")),
            (
                "n = n + EXCLUDED.m",
                UpsertAddOperand::Excluded("m".to_string()),
            ),
            (
                "n = n + excluded.n",
                UpsertAddOperand::Excluded("n".to_string()),
            ),
        ];
        for (set, operand) in cases {
            let sql = format!(
                "INSERT INTO documents (id, n) VALUES (1, 1) ON CONFLICT (id) DO UPDATE SET {set} \
                 USING OPERATION_ID 'op-add-1'"
            );
            let stmt = validate_insert(&sql, &lookup, LedgerMode::Ledgered).expect(&sql);
            let Some(OnConflictClause {
                action: OnConflictAction::DoUpdate { assignments: a, .. },
                ..
            }) = stmt.on_conflict
            else {
                panic!("expected DoUpdate: {sql}");
            };
            let expected = UpsertValue::Add {
                column: "n".to_string(),
                operand,
            };
            assert_eq!(a, vec![("n".to_string(), expected)], "{sql}");
        }
        let sql = "INSERT INTO documents (id, a, b) VALUES (1, 1, 1) ON CONFLICT (id) \
                   DO UPDATE SET a = a + 1, b = EXCLUDED.b USING OPERATION_ID 'op-add-2'";
        let stmt = validate_insert(sql, &lookup, LedgerMode::Ledgered).expect(sql);
        let Some(OnConflictClause {
            action: OnConflictAction::DoUpdate { assignments: a, .. },
            ..
        }) = stmt.on_conflict
        else {
            panic!("expected DoUpdate");
        };
        assert_eq!(a.len(), 2);
        assert!(matches!(a[1].1, UpsertValue::Excluded(_)));
    }

    /// 加算形に当てはまらない右辺は一般の式（`UpsertValue::Expr`。Issue #1739）として受理し、
    /// 修飾列参照を構文段で解決する（`t.n`→`n`、`EXCLUDED.n`→予約接頭辞付き）。
    #[test]
    fn upsert_set_non_add_shapes_parse_as_expr() {
        let lookup = catalog_with(&["documents"]);
        let parse = |set: &str| {
            let sql = format!(
                "INSERT INTO documents (id, n) VALUES (1, 1) ON CONFLICT (id) DO UPDATE SET {set} \
                 USING OPERATION_ID 'op-add-3'"
            );
            validate_insert(&sql, &lookup, LedgerMode::Ledgered).map(|stmt| {
                let Some(OnConflictClause {
                    action: OnConflictAction::DoUpdate { assignments: a, .. },
                    ..
                }) = stmt.on_conflict
                else {
                    panic!("expected DoUpdate: {sql}");
                };
                a
            })
        };
        for set in [
            "n = m + 1",
            "n = 1 + n",
            "n = n - 1",
            "n = n * 2",
            "n = n / 2",
            "n = n + 1 + 2",
            "n = n + 1 * 2",
            "n = (n + 1)",
            "n = documents.n + EXCLUDED.n",
            "n = EXCLUDED.n + 1",
            "n = n + NULL + 1",
            "n = n + 'x' || 'y'",
            "n = coalesce(n, 0) + 1",
        ] {
            let a = parse(set).unwrap_or_else(|e| panic!("{set}: {e:?}"));
            assert!(matches!(a[0].1, UpsertValue::Expr(_)), "{set}: {a:?}");
        }
        // 修飾子の解決: 対象表名は修飾なしの列、EXCLUDED は予約接頭辞つきの列。
        let a = parse("n = documents.n + EXCLUDED.n").expect("qualified");
        let UpsertValue::Expr(Expr::Binary { lhs, rhs, .. }) = &a[0].1 else {
            panic!("expected binary expr");
        };
        assert_eq!(**lhs, Expr::Ident("n".to_string()));
        assert_eq!(
            **rhs,
            Expr::Ident(format!("{}n", crate::sql::upsert_expr::EXCLUDED_PREFIX))
        );
        // 厳密な加算形・EXCLUDED 単独・リテラルは従来の variant のまま（回帰）。
        assert!(matches!(
            parse("n = n + 1").unwrap()[0].1,
            UpsertValue::Add { .. }
        ));
        assert!(matches!(
            parse("n = n + EXCLUDED.n").unwrap()[0].1,
            UpsertValue::Add { .. }
        ));
        assert!(matches!(
            parse("n = EXCLUDED.n").unwrap()[0].1,
            UpsertValue::Excluded(_)
        ));
        assert!(matches!(
            parse("n = 5").unwrap()[0].1,
            UpsertValue::Literal(_)
        ));
        assert!(matches!(
            parse("n = NULL").unwrap()[0].1,
            UpsertValue::Literal(_)
        ));
    }

    /// 構文段で今も拒否する形（未知の修飾子は `42P01`、途中で終わる式・予約接頭辞の偽装は
    /// `42601`）。
    #[test]
    fn upsert_set_expr_syntax_rejects_invalid_shapes() {
        let lookup = catalog_with(&["documents"]);
        for (set, expected) in [
            ("n = n + foo.m", "42P01"),
            ("n = t.n + 1", "42P01"),
            // 厳密な加算形の右辺が数値以外のリテラル 1 個の形は従来どおり（#2425・#2427）。
            ("n = n + NULL", "42601"),
            ("n = n + 'x'", "42601"),
            ("n = n + true", "42601"),
            ("n = foo.m", "42P01"),
            ("n = foo.m * 2", "42P01"),
            ("n = n +", "42601"),
            ("n = n + (", "42601"),
            ("n = \"\u{0}excluded.n\" + 1", "42601"),
        ] {
            let sql = format!(
                "INSERT INTO documents (id, n) VALUES (1, 1) ON CONFLICT (id) DO UPDATE SET {set} \
                 USING OPERATION_ID 'op-add-3'"
            );
            let err = validate_insert(&sql, &lookup, LedgerMode::Ledgered).unwrap_err();
            assert_eq!(err.wire_code(), expected, "{sql}");
        }
    }

    /// `DO UPDATE SET ... WHERE <条件>`（SQL-49 (3)、Issue #1740）の構文段: 修飾列は 1 対 1 に
    /// 正規化され、`RETURNING`／`USING OPERATION_ID` と併用でき、`DO NOTHING WHERE`・
    /// 未知の修飾子・予約接頭辞の偽装・余剰トークンは拒否される。
    #[test]
    fn upsert_do_update_where_parses_and_normalizes_qualifiers() {
        let lookup = catalog_with(&["documents"]);
        let parse = |wh: &str| {
            let sql = format!(
                "INSERT INTO documents (id, n) VALUES (1, 1) ON CONFLICT (id) DO UPDATE SET \
                 n = EXCLUDED.n WHERE {wh} RETURNING n USING OPERATION_ID 'op-w'"
            );
            validate_insert(&sql, &lookup, LedgerMode::Ledgered)
        };
        for wh in [
            "n = 1",
            "documents.n < EXCLUDED.n",
            "excluded.n IS NULL OR (n IN (1, 2) AND NOT (n = 3))",
        ] {
            let stmt = parse(wh).unwrap_or_else(|e| panic!("{wh}: {e:?}"));
            let Some(OnConflictClause {
                action: OnConflictAction::DoUpdate { condition, .. },
                ..
            }) = stmt.on_conflict
            else {
                panic!("expected DoUpdate: {wh}");
            };
            assert!(!condition.is_empty(), "{wh}");
            let dbg = format!("{condition:?}");
            assert!(!dbg.contains("QualifiedIdent"), "{wh}: {dbg}");
            assert!(!dbg.contains("documents."), "{wh}: {dbg}");
        }
        let stmt = parse("documents.n < EXCLUDED.n").expect("qualified");
        let Some(OnConflictClause {
            action: OnConflictAction::DoUpdate { condition, .. },
            ..
        }) = stmt.on_conflict
        else {
            panic!("expected DoUpdate");
        };
        assert!(format!("{condition:?}").contains("excluded.n"));

        assert_eq!(parse("other.n = 1").unwrap_err().wire_code(), "42P01");
        assert_eq!(parse("documents.* = 1").unwrap_err().wire_code(), "42601");
        assert_eq!(parse("n = 1 LIMIT 1").unwrap_err().wire_code(), "42601");
        assert_eq!(parse("").unwrap_err().wire_code(), "42601");
        // `DO NOTHING` に `WHERE` は付けられない（従来どおり余剰トークン）。
        let sql = "INSERT INTO documents (id, n) VALUES (1, 1) ON CONFLICT (id) DO NOTHING \
                   WHERE n = 1 USING OPERATION_ID 'op-w'";
        assert_eq!(
            validate_insert(sql, &lookup, LedgerMode::Ledgered)
                .unwrap_err()
                .wire_code(),
            "42601"
        );
    }

    /// 引用付き `"null"` 列は加算の左オペランドとして受理し、引用なしの `NULL` 定数とは
    /// 区別する（引用なしは従来どおり `42601`）。
    #[test]
    fn upsert_set_add_accepts_quoted_null_column() {
        let lookup = catalog_with(&["documents"]);
        let sql = "INSERT INTO documents (id, \"null\") VALUES (1, 1) ON CONFLICT (id) \
                   DO UPDATE SET \"null\" = \"null\" + 1 USING OPERATION_ID 'op-add-q'";
        let stmt = validate_insert(sql, &lookup, LedgerMode::Ledgered).expect(sql);
        let Some(OnConflictClause {
            action: OnConflictAction::DoUpdate { assignments: a, .. },
            ..
        }) = stmt.on_conflict
        else {
            panic!("expected DoUpdate");
        };
        assert!(matches!(a[0].1, UpsertValue::Add { .. }));
        // 引用なしの `NULL` は加算の左オペランドにならない（加算形ではなく一般の式の経路へ回る。
        // 構文段では列参照 `NULL` 扱いで通り、束縛段が `42703` にする。Issue #1739）。
        // 右オペランドが `NULL` の加算形は従来どおり `42601`（上のテスト参照）。
        let bare = "INSERT INTO documents (id, n) VALUES (1, 1) ON CONFLICT (id) \
                    DO UPDATE SET n = NULL + 1 USING OPERATION_ID 'op-add-q2'";
        let stmt = validate_insert(bare, &lookup, LedgerMode::Ledgered).expect(bare);
        let Some(OnConflictClause {
            action: OnConflictAction::DoUpdate { assignments: a, .. },
            ..
        }) = stmt.on_conflict
        else {
            panic!("expected DoUpdate");
        };
        assert!(matches!(a[0].1, UpsertValue::Expr(_)));
    }

    /// INSERT の VALUES は `NULL`（大小無視）を `InsertLiteral::Null` として受理する
    /// （Issue #1523・SQL-41）。
    #[test]
    fn insert_values_accept_null_literal() {
        let lookup = catalog_with(&["documents"]);
        for kw in ["NULL", "null", "Null"] {
            let sql = format!(
                "INSERT INTO documents (id, embedding, lang) VALUES (1, {kw}, 'x'), (2, 'y', {kw}) \
                 USING OPERATION_ID 'op-null-1'"
            );
            let stmt = validate_insert(&sql, &lookup, LedgerMode::Ledgered).expect(&sql);
            assert_eq!(stmt.rows.len(), 2);
            assert_eq!(stmt.rows[0][1], InsertLiteral::Null);
            assert_eq!(stmt.rows[1][2], InsertLiteral::Null);
        }
        let stmt = validate_insert(
            "INSERT INTO documents (id, lang) VALUES (1, NULL) ON CONFLICT (id) DO NOTHING \
             USING OPERATION_ID 'op-null-2'",
            &lookup,
            LedgerMode::Ledgered,
        )
        .expect("NULL with ON CONFLICT DO NOTHING");
        assert_eq!(stmt.rows[0][1], InsertLiteral::Null);
    }

    /// `NULL` 以外の識別子・符号付き `NULL`・列数不一致は従来どおり拒否する。
    #[test]
    fn insert_values_reject_non_null_identifiers_and_signed_null() {
        let lookup = catalog_with(&["documents"]);
        // 裸の識別子は列参照として 42703（Issue #1543・SQL-45 のポインタ）。
        for (lit, code) in [("foo", "42703"), ("-NULL", "42601"), ("+NULL", "42601")] {
            let sql = format!(
                "INSERT INTO documents (id, lang) VALUES (1, {lit}) USING OPERATION_ID 'op-null-3'"
            );
            let err = validate_insert(&sql, &lookup, LedgerMode::Ledgered).unwrap_err();
            assert_eq!(err.wire_code(), code, "{sql}");
        }
        let err = validate_insert(
            "INSERT INTO documents (id, lang) VALUES (NULL) USING OPERATION_ID 'op-null-4'",
            &lookup,
            LedgerMode::Ledgered,
        )
        .unwrap_err();
        assert_eq!(err.wire_code(), "42601");
    }

    /// UPDATE SET・UPSERT の DO UPDATE SET で `NULL` を `InsertLiteral::Null` として
    /// 受理する（Issue #1524・SQL-41）。大小無視。
    #[test]
    fn null_literal_is_accepted_in_update_set_and_do_update_set() {
        let lookup = catalog_with(&["documents"]);
        for kw in ["NULL", "null", "Null"] {
            let sql = format!(
                "UPDATE documents SET lang = {kw} WHERE id = 1 USING OPERATION_ID 'op-null-5'"
            );
            let stmt = validate_update(&sql, &lookup, LedgerMode::Ledgered).expect("SET NULL");
            assert_eq!(
                stmt.assignments,
                vec![("lang".to_string(), SetValue::Literal(InsertLiteral::Null))]
            );
        }
        let stmt = validate_insert(
            "INSERT INTO documents (id, lang) VALUES (1, 'x') ON CONFLICT (id) DO UPDATE SET \
             lang = NULL USING OPERATION_ID 'op-null-6'",
            &lookup,
            LedgerMode::Ledgered,
        )
        .expect("DO UPDATE SET NULL");
        assert_eq!(
            stmt.on_conflict,
            Some(OnConflictClause {
                target: ConflictTargetSpec::Columns(vec!["id".to_string()]),
                action: OnConflictAction::DoUpdate {
                    assignments: vec![(
                        "lang".to_string(),
                        UpsertValue::Literal(InsertLiteral::Null)
                    )],
                    condition: Vec::new(),
                },
            })
        );
    }

    /// SET・DO UPDATE SET の `-NULL`／`+NULL`／`NULL` 以外の識別子は `42601`。
    #[test]
    fn set_rejects_signed_null_and_other_identifiers() {
        let lookup = catalog_with(&["documents"]);
        for lit in ["-NULL", "+NULL", "foo"] {
            let sql = format!(
                "UPDATE documents SET lang = {lit} WHERE id = 1 USING OPERATION_ID 'op-null-7'"
            );
            // UPDATE SET の右辺は式を受理する（Issue #1544・SQL-45 のポインタ）ため、
            // `+NULL` 以外は構造検証を通り、列参照形（`-NULL` は `0 - NULL`、`foo` は列参照）の
            // 意味論的な拒否は束縛段（`sql::set_expr`）が担う。
            let update_result = validate_update(&sql, &lookup, LedgerMode::Ledgered);
            if lit == "+NULL" {
                assert_eq!(update_result.unwrap_err().wire_code(), "42601", "{sql}");
            } else {
                assert!(
                    matches!(
                        update_result.expect("structure ok").assignments.as_slice(),
                        [(_, SetValue::Expr(_))]
                    ),
                    "{sql}"
                );
            }
            let sql = format!(
                "INSERT INTO documents (id, lang) VALUES (1, 'x') ON CONFLICT (id) DO UPDATE \
                 SET lang = {lit} USING OPERATION_ID 'op-null-8'"
            );
            // DO UPDATE SET の右辺も UPDATE SET と同じ式を受理する（Issue #1739）。`+NULL` 以外は
            // 構造検証を通り、列参照形の拒否は束縛段が担う。
            let insert_result = validate_insert(&sql, &lookup, LedgerMode::Ledgered);
            if lit == "+NULL" {
                assert_eq!(insert_result.unwrap_err().wire_code(), "42601", "{sql}");
            } else {
                let stmt = insert_result.expect("structure ok");
                let Some(OnConflictClause {
                    action: OnConflictAction::DoUpdate { assignments: a, .. },
                    ..
                }) = stmt.on_conflict
                else {
                    panic!("expected DoUpdate: {sql}");
                };
                assert!(matches!(a[0].1, UpsertValue::Expr(_)), "{sql}");
            }
        }
    }

    /// 引用付き `"NULL"` は NULL 定数として受理しない（Issue #1524 レビュー指摘。
    /// UPDATE SET・DO UPDATE SET・DEFAULT・INSERT VALUES のいずれも `42601`）。
    #[test]
    fn quoted_null_is_not_a_null_literal() {
        let lookup = catalog_with(&["documents"]);
        // UPDATE SET の引用付き `"NULL"` は NULL 定数ではなく列参照として解析する
        // （Issue #1544。NULL 定数にならないことが本テストの契約。列の実在は束縛段が判定）。
        let stmt = validate_update(
            "UPDATE documents SET lang = \"NULL\" WHERE id = 1 USING OPERATION_ID 'op-q-1'",
            &lookup,
            LedgerMode::Ledgered,
        )
        .expect("structure ok");
        assert_eq!(
            stmt.assignments,
            vec![(
                "lang".to_string(),
                SetValue::Expr(Expr::Ident("NULL".to_string()))
            )]
        );
        // DO UPDATE SET も同じく列参照として解析する（Issue #1739。NULL 定数にならないことが契約）。
        let stmt = validate_insert(
            "INSERT INTO documents (id, lang) VALUES (1, 'x') ON CONFLICT (id) DO UPDATE SET \
             lang = \"null\" USING OPERATION_ID 'op-q-2'",
            &lookup,
            LedgerMode::Ledgered,
        )
        .expect("structure ok");
        assert_eq!(
            stmt.on_conflict,
            Some(OnConflictClause {
                target: ConflictTargetSpec::Columns(vec!["id".to_string()]),
                action: OnConflictAction::DoUpdate {
                    assignments: vec![(
                        "lang".to_string(),
                        UpsertValue::Expr(Expr::Ident("null".to_string()))
                    )],
                    condition: Vec::new(),
                },
            })
        );
        let err = validate_insert(
            "INSERT INTO documents (id, lang) VALUES (1, \"NULL\") USING OPERATION_ID 'op-q-3'",
            &lookup,
            LedgerMode::Ledgered,
        )
        .unwrap_err();
        assert_eq!(err.wire_code(), "42703");
        let tokens = crate::sql::lexer::tokenize_marked("DEFAULT \"NULL\"").expect("tokenize");
        assert_eq!(
            Parser::new(&tokens)
                .parse_column_constraints()
                .unwrap_err()
                .wire_code(),
            "42703"
        );
    }

    /// 識別子位置の引用付き `"null"`／`"NULL"` は従来どおり識別子として受理する
    /// （Issue #1524 レビュー指摘。値位置のみ NULL 定数を拒否する）。
    #[test]
    fn quoted_null_is_still_accepted_as_identifier() {
        let lookup = catalog_with(&["documents", "null", "NULL"]);
        for sql in [
            "SELECT * FROM \"null\" ORDER BY embedding <=> '[0.1,0.2]' LIMIT 20",
            "SELECT * FROM \"NULL\" ORDER BY embedding <=> '[0.1,0.2]' LIMIT 20",
            "SELECT \"null\" FROM documents ORDER BY embedding <=> '[0.1,0.2]' LIMIT 20",
            "SELECT \"NULL\" FROM documents ORDER BY embedding <=> '[0.1,0.2]' LIMIT 20",
            "SELECT * FROM documents WHERE \"null\" = 'x' ORDER BY embedding <=> '[0.1,0.2]' LIMIT 20",
        ] {
            let tokens = crate::sql::lexer::tokenize_marked(sql).expect("tokenize");
            let tokens = crate::sql::lexer::demote_quoted_null(tokens);
            validate_sql_tokens(&tokens, &lookup).unwrap_or_else(|e| panic!("{sql}: {e:?}"));
        }
        // 許可リストの Parser は引用付き NULL を含む生トークン列でも識別子位置を受理する。
        let lookup = catalog_with(&["documents", "null"]);
        let tokens = crate::sql::lexer::tokenize_marked(
            "SELECT * FROM \"null\" ORDER BY embedding <=> '[0.1,0.2]' LIMIT 20",
        )
        .expect("tokenize");
        validate_sql_tokens(&tokens, &lookup).expect("quoted null table name");
        let stmt = validate_update(
            "UPDATE \"null\" SET \"null\" = 'x' WHERE id = 1 USING OPERATION_ID 'op-q-4'",
            &lookup,
            LedgerMode::Ledgered,
        )
        .expect("quoted null table and column names in UPDATE");
        assert_eq!(
            stmt.assignments,
            vec![(
                "null".to_string(),
                SetValue::Literal(InsertLiteral::String("x".to_string()))
            )]
        );
    }
    /// `DEFAULT NULL` は受理して既定値なし（`default: None`）へ正規化し、重複 `DEFAULT`
    /// は順序を問わず `42601`（Issue #1524・SQL-41）。
    #[test]
    fn default_null_is_normalized_to_no_default() {
        let parse = |sql: &str| {
            let tokens = crate::sql::lexer::tokenize(sql).expect("tokenize");
            Parser::new(&tokens).parse_column_constraints()
        };
        let c = parse("DEFAULT NULL").expect("DEFAULT NULL");
        assert_eq!(c.default, None);
        assert!(!c.not_null);
        let c = parse("NOT NULL DEFAULT null").expect("NOT NULL DEFAULT NULL");
        assert_eq!(c.default, None);
        assert!(c.not_null);
        let c = parse("DEFAULT 'x'").expect("DEFAULT literal");
        assert_eq!(c.default, Some(InsertLiteral::String("x".to_string())));
        for sql in [
            "DEFAULT NULL DEFAULT 'x'",
            "DEFAULT 'x' DEFAULT NULL",
            "DEFAULT NULL DEFAULT NULL",
        ] {
            assert_eq!(parse(sql).unwrap_err().wire_code(), "42601", "{sql}");
        }
        assert_eq!(parse("DEFAULT -NULL").unwrap_err().wire_code(), "42601");
        // 列参照は 42703（Issue #1543・SQL-45 のポインタ）。
        assert_eq!(parse("DEFAULT foo").unwrap_err().wire_code(), "42703");
    }

    /// 時刻値関数の `DEFAULT`（SQL-37・TABLE-16・Issue #1587）。単独形だけを時刻 DEFAULT として
    /// 受理し、複合式・入れ子・未対応の関数は従来どおり拒否する。
    #[test]
    fn time_function_default_accepts_only_standalone_forms() {
        use crate::catalog::TimeDefault;
        let parse = |sql: &str| {
            let tokens = crate::sql::lexer::tokenize(sql).expect("tokenize");
            Parser::new(&tokens).parse_column_constraints()
        };
        for (sql, expected) in [
            ("DEFAULT now()", TimeDefault::Now),
            ("DEFAULT NOW ( )", TimeDefault::Now),
            (
                "DEFAULT transaction_timestamp()",
                TimeDefault::TransactionTimestamp,
            ),
            (
                "DEFAULT CURRENT_TIMESTAMP",
                TimeDefault::CurrentTimestamp(None),
            ),
            (
                "DEFAULT current_timestamp(3)",
                TimeDefault::CurrentTimestamp(Some(3)),
            ),
            ("DEFAULT LOCALTIMESTAMP", TimeDefault::LocalTimestamp(None)),
            (
                "DEFAULT LOCALTIMESTAMP(0)",
                TimeDefault::LocalTimestamp(Some(0)),
            ),
            ("DEFAULT CURRENT_DATE", TimeDefault::CurrentDate),
            (
                "DEFAULT statement_timestamp()",
                TimeDefault::StatementTimestamp,
            ),
            ("DEFAULT clock_timestamp()", TimeDefault::ClockTimestamp),
            ("DEFAULT LOCALTIME", TimeDefault::LocalTime(None)),
            ("DEFAULT localtime(3)", TimeDefault::LocalTime(Some(3))),
        ] {
            let c = parse(sql).unwrap_or_else(|e| panic!("{sql}: {e:?}"));
            assert_eq!(c.time_default, Some(expected), "{sql}");
            assert_eq!(c.default, None, "{sql}");
        }
        // 後続の列制約と共存できる。
        let c = parse("DEFAULT now() NOT NULL UNIQUE").unwrap();
        assert_eq!(c.time_default, Some(TimeDefault::Now));
        assert!(c.not_null && c.unique);
        // 精度 7 は 22023、複合式・CAST・CURRENT_TIME（timetz 未実装）は 42601。
        assert_eq!(
            parse("DEFAULT CURRENT_TIMESTAMP(7)")
                .unwrap_err()
                .wire_code(),
            "22023"
        );
        for (sql, code) in [
            ("DEFAULT now() + 1", "42601"),
            // `::` は CAST と同じく定数式では未対応（0A000。Issue #1593）。
            ("DEFAULT now()::text", "0A000"),
            ("DEFAULT now() || 'x'", "42601"),
            ("DEFAULT CURRENT_TIMESTAMP + 1", "42601"),
            ("DEFAULT statement_timestamp() + 1", "42601"),
            ("DEFAULT clock_timestamp()::text", "0A000"),
            ("DEFAULT CURRENT_TIME", "42601"),
            ("DEFAULT LOCALTIME + 1", "42601"),
        ] {
            assert_eq!(parse(sql).unwrap_err().wire_code(), code, "{sql}");
        }
        // 引用付き識別子は時刻 DEFAULT にしない（定数式経路が従来どおり拒否する）。
        let marked =
            crate::sql::lexer::tokenize_marked("DEFAULT \"current_timestamp\"").expect("tokenize");
        assert_eq!(
            Parser::new(&marked)
                .parse_column_constraints()
                .unwrap_err()
                .wire_code(),
            "42601"
        );
    }

    /// `DEFAULT` と VALUES の定数式（Issue #1543・SQL-45 のポインタ）。
    #[test]
    fn const_expr_default_and_values() {
        let parse = |sql: &str| {
            let tokens = crate::sql::lexer::tokenize(sql).expect("tokenize");
            Parser::new(&tokens).parse_column_constraints()
        };
        let c = parse("DEFAULT 1+1").unwrap();
        assert_eq!(c.default, Some(InsertLiteral::Number("2".to_string())));
        let c = parse("DEFAULT upper('a') NOT NULL UNIQUE").unwrap();
        assert_eq!(c.default, Some(InsertLiteral::String("A".to_string())));
        assert!(c.not_null && c.unique);
        assert_eq!(parse("DEFAULT NULLIF(1,1)").unwrap().default, None);
        assert_eq!(
            parse("DEFAULT -5").unwrap().default,
            Some(InsertLiteral::Number("-5".into()))
        );
        assert_eq!(
            parse("DEFAULT +1").unwrap().default,
            Some(InsertLiteral::Number("+1".into()))
        );
        assert_eq!(
            parse("DEFAULT true").unwrap().default,
            Some(InsertLiteral::Bool(true))
        );
        assert_eq!(parse("DEFAULT -(1+2)").unwrap_err().wire_code(), "42601");
        assert_eq!(parse("DEFAULT n + 1").unwrap_err().wire_code(), "42703");
        // NULL は定数式の内部でも受理する（算術では NULL 伝播）。引用された "null" は
        // 列参照のまま 42703。
        assert_eq!(parse("DEFAULT (NULL)").unwrap().default, None);
        assert_eq!(parse("DEFAULT NULL + 1").unwrap().default, None);
        let marked = crate::sql::lexer::tokenize_marked("DEFAULT (\"null\")").expect("tokenize");
        assert_eq!(
            Parser::new(&marked)
                .parse_column_constraints()
                .unwrap_err()
                .wire_code(),
            "42703"
        );
        assert_eq!(
            parse("DEFAULT 9007199254740992 + 1 - 9007199254740992")
                .unwrap_err()
                .wire_code(),
            "22003"
        );

        let lookup = catalog_with(&["documents"]);
        let ok = validate_insert(
            "INSERT INTO documents (id, body) VALUES (1+1, upper('a')), (3, 'x') \
             USING OPERATION_ID 'op-ce-1'",
            &lookup,
            LedgerMode::Ledgered,
        )
        .unwrap();
        assert_eq!(
            ok.rows[0],
            vec![
                InsertLiteral::Number("2".into()),
                InsertLiteral::String("A".into())
            ]
        );
        let nulls = validate_insert(
            "INSERT INTO documents (id, body) VALUES (1, (NULL)), (2, NULL + 1) \
             USING OPERATION_ID 'op-ce-null'",
            &lookup,
            LedgerMode::Ledgered,
        )
        .unwrap();
        assert_eq!(nulls.rows[0][1], InsertLiteral::Null);
        assert_eq!(nulls.rows[1][1], InsertLiteral::Null);
        let many = format!(
            "INSERT INTO documents (id) VALUES {} USING OPERATION_ID 'op-ce-2'",
            vec!["(1+1)"; 600].join(", ")
        );
        validate_insert(&many, &lookup, LedgerMode::Ledgered).unwrap();
        let err = validate_insert(
            "INSERT INTO documents (id, body) VALUES (1, n) USING OPERATION_ID 'op-ce-3'",
            &lookup,
            LedgerMode::Ledgered,
        )
        .unwrap_err();
        assert_eq!(err.wire_code(), "42703");
        // UPDATE SET は構文木のまま式を受理する（Issue #1544。型照合・評価は束縛段以降）。
        let stmt = validate_update(
            "UPDATE documents SET body = 1+1 WHERE id = 1 USING OPERATION_ID 'op-ce-4'",
            &lookup,
            LedgerMode::Ledgered,
        )
        .expect("structure ok");
        assert!(matches!(
            stmt.assignments.as_slice(),
            [(_, SetValue::Expr(Expr::Binary { .. }))]
        ));
    }

    /// `UPDATE ... SET` の右辺は平易なリテラルなら従来どおり `SetValue::Literal`
    /// （`content_hash` が不変の前提）、列参照・算術・組み込み関数・単項マイナスは
    /// `SetValue::Expr`（Issue #1544・SQL-45 のポインタ）。
    #[test]
    fn update_set_accepts_literal_and_expression_forms() {
        let lookup = catalog_with(&["documents"]);
        let parse = |rhs: &str| {
            validate_update(
                &format!(
                    "UPDATE documents SET n = {rhs} WHERE id = 1 USING OPERATION_ID 'op-se-1'"
                ),
                &lookup,
                LedgerMode::Ledgered,
            )
            .map(|u| u.assignments)
        };
        for (rhs, expect_literal) in [
            ("5", true),
            ("-5", true),
            ("'x'", true),
            ("true", true),
            ("NULL", true),
            ("n + 1", false),
            ("m", false),
            ("upper(t)", false),
            ("-n", false),
            ("(5)", false),
            ("5 + 0", false),
            ("+5 + 1", false),
            ("+1 * n", false),
            ("(+5)", false),
            ("CASE WHEN n > 1 THEN 1 ELSE 2 END", false),
        ] {
            let a = parse(rhs).unwrap_or_else(|e| panic!("{rhs}: {e:?}"));
            assert_eq!(a.len(), 1, "{rhs}");
            assert_eq!(
                matches!(a[0].1, SetValue::Literal(_)),
                expect_literal,
                "{rhs}: {:?}",
                a[0].1
            );
        }
        assert_eq!(
            parse("5").unwrap()[0].1,
            SetValue::Literal(InsertLiteral::Number("5".to_string()))
        );
        // 構造として受理しない形は従来どおり `42601`。
        for rhs in ["+n", "n +", "n + (", "1 2"] {
            assert_eq!(parse(rhs).unwrap_err().wire_code(), "42601", "{rhs}");
        }
    }

    /// `SET c = DEFAULT`（SQL-50・Issue #1746）は大小無視で `SetValue::Default`、引用付きは列参照、
    /// 余剰トークンは `42601`。
    #[test]
    fn update_set_default_keyword_is_parsed_only_when_bare() {
        let lookup = catalog_with(&["documents"]);
        let parse = |rhs: &str| {
            validate_update(
                &format!(
                    "UPDATE documents SET n = {rhs} WHERE id = 1 USING OPERATION_ID 'op-sd-1'"
                ),
                &lookup,
                LedgerMode::Ledgered,
            )
            .map(|u| u.assignments)
        };
        for rhs in ["DEFAULT", "default", "Default"] {
            assert_eq!(parse(rhs).unwrap()[0].1, SetValue::Default, "{rhs}");
        }
        assert!(matches!(
            parse("\"DEFAULT\"").unwrap()[0].1,
            SetValue::Expr(_)
        ));
        for rhs in ["DEFAULT + 1", "DEFAULT::int", "DEFAULT DEFAULT"] {
            assert_eq!(parse(rhs).unwrap_err().wire_code(), "42601", "{rhs}");
        }
    }

    /// 行値の代入 `SET (a, b) = (...)`（SQL-50 (3)・Issue #1747）は列ごとの代入へ宣言順に展開する。
    /// 個数不一致・1 列の括弧のみは `42601`、部分クエリ源は `0A000`、累計の個数上限は `42601`。
    #[test]
    fn update_set_row_value_expands_to_per_column_assignments() {
        let lookup = catalog_with(&["documents"]);
        let parse = |set: &str| {
            validate_update(
                &format!("UPDATE documents SET {set} WHERE id = 1 USING OPERATION_ID 'op-rv-1'"),
                &lookup,
                LedgerMode::Ledgered,
            )
            .map(|u| u.assignments)
        };
        let expected = parse("n = 1, o = 'x'").unwrap();
        assert_eq!(parse("(n, o) = (1, 'x')").unwrap(), expected);
        assert_eq!(parse("(n, o) = ROW(1, 'x')").unwrap(), expected);
        assert_eq!(parse("n = 1, (o) = ROW('x')").unwrap(), expected);
        let d = parse("(n, o) = (DEFAULT, 1 + 1)").unwrap();
        assert_eq!(d[0].1, SetValue::Default);
        assert!(matches!(d[1].1, SetValue::Expr(_)));
        for set in [
            "(n, o) = (1)",
            "(n, o) = (1, 2, 3)",
            "(n, o) = ROW()",
            "(n) = (1)",
            "() = ()",
            "(n, o) = 1",
            "(n, o) =",
        ] {
            assert_eq!(parse(set).unwrap_err().wire_code(), "42601", "{set}");
        }
        for set in [
            "(n, o) = (SELECT 1, 2)",
            "(n, o) = (VALUES (1, 2))",
            "(n, o) = (WITH c AS (SELECT 1) SELECT 1, 2)",
            "(n, o) = (WITH RECURSIVE c AS (SELECT 1) SELECT 1, 2)",
        ] {
            assert_eq!(parse(set).unwrap_err().wire_code(), "0A000", "{set}");
        }
        // `values` / `with` は通常の識別子: 先頭スロットの列参照として受理する。
        for set in ["(n, o) = (values, 1)", "(n, o) = (with, 1)"] {
            assert!(parse(set).is_ok(), "{set}");
        }
        let cols: Vec<String> = (0..=MAX_UPDATE_SET_ASSIGNMENTS)
            .map(|i| format!("c{i}"))
            .collect();
        let vals = vec!["1"; cols.len()].join(", ");
        let over = format!("({}) = ({vals})", cols.join(", "));
        assert_eq!(parse(&over).unwrap_err().wire_code(), "42601");
    }

    /// 式の複数 SET・述語形でも構文木のまま保持し、宣言順を保つ。
    /// `ON CONFLICT ... DO UPDATE SET` の一般の式は Issue #1739 で受理する
    /// （`UpsertValue::Expr`。加算形だけは Issue #2425 の `UpsertValue::Add` のまま）。
    #[test]
    fn update_set_expressions_in_predicate_form_and_upsert_accepts_expr() {
        let lookup = catalog_with(&["documents"]);
        let stmt = validate_update_form(
            "UPDATE documents SET a = 1, b = a + 1 WHERE lang = 'ja' USING OPERATION_ID 'op-se-2'",
            &lookup,
            LedgerMode::Ledgered,
        )
        .expect("predicate form with expression");
        let ValidatedUpdateForm::Predicate(p) = stmt else {
            panic!("expected predicate form");
        };
        assert_eq!(p.assignments().len(), 2);
        assert!(matches!(p.assignments()[0].1, SetValue::Literal(_)));
        assert!(matches!(p.assignments()[1].1, SetValue::Expr(_)));
        let stmt = validate_insert(
            "INSERT INTO documents (id, n) VALUES (1, 1) ON CONFLICT (id) DO UPDATE SET \
             n = n * 2 USING OPERATION_ID 'op-se-3'",
            &lookup,
            LedgerMode::Ledgered,
        )
        .expect("general expression in DO UPDATE SET");
        let Some(OnConflictClause {
            action: OnConflictAction::DoUpdate { assignments: a, .. },
            ..
        }) = stmt.on_conflict
        else {
            panic!("expected DoUpdate");
        };
        assert!(matches!(a[0].1, UpsertValue::Expr(_)));
    }

    #[test]
    fn accepts_upsert_omitted_target_do_nothing() {
        // SQL-49（Issue #1736）: 対象省略の `DO NOTHING` は構文段階で受理する。
        let lookup = catalog_with(&["documents"]);
        let stmt = validate_insert(
            "INSERT INTO documents (id) VALUES (1) ON CONFLICT DO NOTHING \
             USING OPERATION_ID 'op-upsert-4'",
            &lookup,
            LedgerMode::Ledgered,
        )
        .unwrap();
        assert_eq!(
            stmt.on_conflict,
            Some(OnConflictClause {
                target: ConflictTargetSpec::Omitted,
                action: OnConflictAction::DoNothing,
            })
        );
    }

    #[test]
    fn rejects_upsert_omitted_target_do_update_and_other_target_forms() {
        // 対象省略の `DO UPDATE`・空の列リストは 42601（`ON CONSTRAINT` は Issue #1737 で受理）（SQL-49）。
        let lookup = catalog_with(&["documents"]);
        for sql in [
            "INSERT INTO documents (id) VALUES (1) ON CONFLICT DO UPDATE SET lang = NULL \
             USING OPERATION_ID 'op-a'",
            "INSERT INTO documents (id) VALUES (1) ON CONFLICT () DO NOTHING \
             USING OPERATION_ID 'op-c'",
        ] {
            let err = validate_insert(sql, &lookup, LedgerMode::Ledgered).unwrap_err();
            assert_eq!(err.wire_code(), "42601", "{sql}");
        }
    }

    #[test]
    fn accepts_upsert_non_id_target_column_at_syntax_level() {
        // 構文段階（本モジュール）では `id` に限らず任意の列名を対象列として
        // 受理する（TABLE-16、Issue #1074）。宣言済み UNIQUE 制約の構成列
        // 集合と一致するかの意味論的検証は `sql::parser::bind_upsert_form` の
        // 責務であり、`lang` に UNIQUE 制約が無いスキーマでは最終的に `42P10`
        // になることを `sql::parser` の結合テストで固定する
        // （`rejects_upsert_target_not_matching_any_unique_constraint` 参照）。
        let lookup = catalog_with(&["documents"]);
        let stmt = validate_insert(
            "INSERT INTO documents (id, lang) VALUES (1, 'ja') ON CONFLICT (lang) DO NOTHING \
             USING OPERATION_ID 'op-upsert-5'",
            &lookup,
            LedgerMode::Ledgered,
        )
        .expect("non-id target column should be accepted at the syntax level");
        assert_eq!(
            stmt.on_conflict,
            Some(OnConflictClause {
                target: ConflictTargetSpec::Columns(vec!["lang".to_string()]),
                action: OnConflictAction::DoNothing,
            })
        );
    }

    #[test]
    fn accepts_upsert_target_column_with_mismatched_case_at_syntax_level() {
        // `id` は列識別子であり、`ON`/`CONFLICT`/`DO` のような文脈的キーワード
        // ではない（大文字小文字保存・区別。`parse_on_conflict_clause` の
        // ドキュメンテーションコメント参照。cursor(Bugbot) 指摘
        // https://github.com/Fandhe-AI/vector-db/pull/990#discussion_r4075151521）。
        // 構文段階では任意の識別子を対象列として受理するため（Issue #1074）、
        // `(ID)`／`(Id)` もここでは受理される。大小文字違いが実在しない列名と
        // して最終的に `42601` になることは bind 段（`sql::parser`）の結合
        // テストで固定する（`rejects_upsert_target_column_with_mismatched_case`
        // 参照）。
        let lookup = catalog_with(&["documents"]);
        for target in ["ID", "Id"] {
            let sql = format!(
                "INSERT INTO documents (id) VALUES (1) ON CONFLICT ({target}) DO NOTHING \
                 USING OPERATION_ID 'op-upsert-case'"
            );
            let stmt = validate_insert(&sql, &lookup, LedgerMode::Ledgered)
                .expect("case-mismatched target column should be accepted at the syntax level");
            assert_eq!(
                stmt.on_conflict,
                Some(OnConflictClause {
                    target: ConflictTargetSpec::Columns(vec![target.to_string()]),
                    action: OnConflictAction::DoNothing,
                })
            );
        }
    }

    #[test]
    fn accepts_upsert_multiple_target_columns_at_syntax_level() {
        // 複数対象列の構文自体は本モジュールで受理する（TABLE-16、Issue #1074）。
        // `(id, lang)` が宣言済み UNIQUE 制約のいずれとも一致しない場合に
        // 最終的に `42601` になることは bind 段の結合テストで固定する
        // （`rejects_upsert_target_not_matching_any_unique_constraint` 参照）。
        let lookup = catalog_with(&["documents"]);
        let stmt = validate_insert(
            "INSERT INTO documents (id, lang) VALUES (1, 'ja') ON CONFLICT (id, lang) DO NOTHING \
             USING OPERATION_ID 'op-upsert-6'",
            &lookup,
            LedgerMode::Ledgered,
        )
        .expect("multiple target columns should be accepted at the syntax level");
        assert_eq!(
            stmt.on_conflict,
            Some(OnConflictClause {
                target: ConflictTargetSpec::Columns(vec!["id".to_string(), "lang".to_string()]),
                action: OnConflictAction::DoNothing,
            })
        );
    }

    #[test]
    fn rejects_upsert_target_column_count_over_limit() {
        // 列数上限（[`crate::catalog::MAX_UNIQUE_CONSTRAINT_COLUMNS`]）超過は
        // 構文段階で `42601`（TABLE-16、Issue #1074）。
        let lookup = catalog_with(&["documents"]);
        let target_list = (0..=crate::catalog::MAX_UNIQUE_CONSTRAINT_COLUMNS)
            .map(|i| format!("c{i}"))
            .collect::<Vec<_>>()
            .join(", ");
        let sql = format!(
            "INSERT INTO documents (id) VALUES (1) ON CONFLICT ({target_list}) DO NOTHING \
             USING OPERATION_ID 'op-upsert-too-many-targets'"
        );
        let err = validate_insert(&sql, &lookup, LedgerMode::Ledgered).unwrap_err();
        assert_eq!(err.wire_code(), "42601");
    }

    #[test]
    fn rejects_upsert_duplicate_target_column() {
        // 対象列名の重複は構文段階で `42601`（TABLE-16、Issue #1074）。
        let lookup = catalog_with(&["documents"]);
        let err = validate_insert(
            "INSERT INTO documents (id, lang) VALUES (1, 'ja') ON CONFLICT (lang, lang) \
             DO NOTHING USING OPERATION_ID 'op-upsert-dup-target'",
            &lookup,
            LedgerMode::Ledgered,
        )
        .unwrap_err();
        assert_eq!(err.wire_code(), "42601");
    }

    #[test]
    fn accepts_upsert_on_constraint_form() {
        let lookup = catalog_with(&["documents"]);
        let stmt = validate_insert(
            "INSERT INTO documents (id) VALUES (1) ON CONFLICT ON CONSTRAINT documents_pkey \
             DO NOTHING USING OPERATION_ID 'op-upsert-7'",
            &lookup,
            LedgerMode::Ledgered,
        )
        .unwrap();
        assert_eq!(
            stmt.on_conflict,
            Some(OnConflictClause {
                target: ConflictTargetSpec::Constraint("documents_pkey".to_string()),
                action: OnConflictAction::DoNothing,
            })
        );
    }

