    /// `INSERT ... SELECT`（SQL-51・Issue #1732）の構文段。問い合わせ span の区切り・後続句・拒否形。
    fn parse_insert_any(
        sql: &str,
        mode: LedgerMode,
    ) -> Result<ParsedInsertTokens, SqlSurfaceError> {
        let tokens = lexer::tokenize(sql).expect("tokenize");
        parse_insert_any_shape_tokens_with_limit(&tokens, mode, None)
    }

    /// Issue #2615: 括弧深さ 0 の `LIMIT` だけを数える（サブクエリ・括弧内・文字列リテラル中は数えない）。
    #[test]
    fn has_top_level_limit_ignores_nested_and_literal_limit() {
        let tok = |sql: &str| lexer::tokenize(sql).expect("tokenize");
        assert!(has_top_level_limit(&tok("SELECT a FROM t LIMIT 3")));
        assert!(has_top_level_limit(&tok(
            "SELECT a FROM t ORDER BY a LIMIT 3 OFFSET 1"
        )));
        assert!(!has_top_level_limit(&tok("SELECT a FROM t")));
        assert!(!has_top_level_limit(&tok(
            "SELECT a FROM t WHERE a IN (SELECT a FROM u LIMIT 2)"
        )));
        assert!(!has_top_level_limit(&tok(
            "(SELECT a FROM t LIMIT 1) UNION ALL (SELECT a FROM u LIMIT 1)"
        )));
        assert!(!has_top_level_limit(&tok(
            "SELECT a FROM t WHERE b = 'limit'"
        )));
    }

    #[test]
    fn insert_select_span_is_cut_at_top_level_clauses_only() {
        // JOIN の `ON`・`USING (...)`・`USING PLAN(...)` で切らず、`RETURNING`／`USING OPERATION_ID`／`;` で切る。
        let sql = "INSERT INTO t (a) SELECT x.a FROM x JOIN y ON x.a = y.a LIMIT 3 \
                   RETURNING a USING OPERATION_ID 'op-1';";
        let ParsedInsertTokens::Select(shape) =
            parse_insert_any(sql, LedgerMode::Ledgered).expect("parse")
        else {
            panic!("expected Select shape");
        };
        let tail = format!("{:?}", shape.query_tokens.last().expect("non-empty"));
        assert!(tail.contains('3'), "span must end at LIMIT 3: {tail}");
        assert!(shape.returning.is_some());
        assert!(shape.operation_id.is_some());

        let sql = "INSERT INTO t (a) SELECT a FROM x USING PLAN(retrieve = 'q') LIMIT 3";
        let ParsedInsertTokens::Select(shape) =
            parse_insert_any(sql, LedgerMode::CompareOnlyWithoutLedger).expect("parse")
        else {
            panic!("expected Select shape");
        };
        assert!(shape.operation_id.is_none());
        assert!(
            shape.query_tokens.len() > 8,
            "USING PLAN must stay inside the span"
        );
    }

    #[test]
    fn insert_select_span_keeps_clause_names_used_as_identifiers() {
        let mode = LedgerMode::CompareOnlyWithoutLedger;
        for sql in [
            "INSERT INTO t (a) SELECT returning FROM x LIMIT 1",
            "INSERT INTO t (a) SELECT x.returning FROM x LIMIT 1",
            "INSERT INTO t (a) SELECT a AS returning FROM x LIMIT 1",
            "INSERT INTO t (a) SELECT conflict FROM x LIMIT 1",
            "INSERT INTO t (a) SELECT a FROM x JOIN y ON conflict = y.a LIMIT 1",
            "INSERT INTO t (a) SELECT a FROM x JOIN y ON x.a = returning LIMIT 1",
            "INSERT INTO t (a) SELECT a FROM x ORDER BY returning LIMIT 1",
        ] {
            let ParsedInsertTokens::Select(shape) = parse_insert_any(sql, mode).expect(sql) else {
                panic!("expected Select shape: {sql}");
            };
            assert!(shape.returning.is_none(), "{sql}");
            let n = lexer::tokenize(sql).expect("tokenize").len();
            assert_eq!(shape.query_tokens.len() + 6, n, "span must be whole: {sql}");
        }
        // 配列コンストラクタ・添字の終端 `]` の直後の `RETURNING` も句境界になる。
        for sql in [
            "INSERT INTO t (a) SELECT ARRAY[1, 2] RETURNING a",
            "INSERT INTO t (a) SELECT b[1] FROM x RETURNING a",
        ] {
            let ParsedInsertTokens::Select(shape) = parse_insert_any(sql, mode).expect(sql) else {
                panic!("expected Select shape: {sql}");
            };
            assert!(shape.returning.is_some(), "{sql}");
        }
        // `AS` 直後の別名が演算子語と同じ綴りでも `RETURNING` は句境界になる。
        for sql in [
            "INSERT INTO t (a) SELECT 1 AS desc RETURNING a",
            "INSERT INTO t (a) SELECT a AS asc FROM x RETURNING a",
        ] {
            let ParsedInsertTokens::Select(shape) = parse_insert_any(sql, mode).expect(sql) else {
                panic!("expected Select shape: {sql}");
            };
            assert!(shape.returning.is_some(), "{sql}");
        }
        // `ORDER BY` の方向指定（`NULLS FIRST/LAST` 含む）の後の `RETURNING` も句境界になる。
        for sql in [
            "INSERT INTO t (a) SELECT a FROM x GROUP BY a ORDER BY a DESC RETURNING a",
            "INSERT INTO t (a) SELECT a FROM x ORDER BY a ASC RETURNING a",
            "INSERT INTO t (a) SELECT a FROM x ORDER BY a DESC NULLS LAST RETURNING a",
            "INSERT INTO t (a) SELECT a FROM x ORDER BY a NULLS FIRST RETURNING a",
            "INSERT INTO t (a) SELECT a FROM x ORDER BY b, a DESC RETURNING a",
        ] {
            let ParsedInsertTokens::Select(shape) = parse_insert_any(sql, mode).expect(sql) else {
                panic!("expected Select shape: {sql}");
            };
            assert!(shape.returning.is_some(), "{sql}");
        }
        // 列名・別名の `desc` は方向指定とみなさず範囲に残す（従来の保護）。
        for sql in [
            "INSERT INTO t (a) SELECT desc returning FROM x",
            "INSERT INTO t (a) SELECT a FROM x ORDER BY desc returning",
        ] {
            let ParsedInsertTokens::Select(shape) = parse_insert_any(sql, mode).expect(sql) else {
                panic!("expected Select shape: {sql}");
            };
            assert!(shape.returning.is_none(), "{sql}");
        }
        // 本物の句は従来どおり境界になる。
        let ParsedInsertTokens::Select(shape) = parse_insert_any(
            "INSERT INTO t (a) SELECT a FROM x JOIN y ON x.a = y.a LIMIT 1 RETURNING a",
            mode,
        )
        .expect("parse") else {
            panic!("expected Select shape");
        };
        assert!(shape.returning.is_some());
        // JOIN の `ON` 述語の後の `ON CONFLICT` は句として認識される（Issue #2614）。
        let ParsedInsertTokens::Select(shape) = parse_insert_any(
            "INSERT INTO t (a) SELECT a FROM x JOIN y ON x.a = y.a LIMIT 1 ON CONFLICT (a) DO NOTHING",
            mode,
        )
        .expect("parse") else {
            panic!("expected Select shape");
        };
        assert!(shape.on_conflict.is_some());
        // 内側の範囲には ON CONFLICT 句を含めない。
        assert!(shape
            .query_tokens
            .iter()
            .all(|t| !matches!(t, Token::Ident(w) if w.eq_ignore_ascii_case("CONFLICT"))));
    }

    /// `INSERT ... SELECT ... ON CONFLICT` の受理形（Issue #2614。SQL-51・SQL-49 のポインタ）。
    #[test]
    fn insert_select_accepts_on_conflict_forms() {
        let mode = LedgerMode::CompareOnlyWithoutLedger;
        for sql in [
            "INSERT INTO t (a) SELECT a FROM x ON CONFLICT (a) DO NOTHING",
            "INSERT INTO t (a, b) SELECT a, b FROM x ON CONFLICT (a) DO UPDATE SET b = EXCLUDED.b",
            "INSERT INTO t (a, b) SELECT a, b FROM x ON CONFLICT ON CONSTRAINT uq DO NOTHING",
            "INSERT INTO t (a) SELECT a FROM x ON CONFLICT DO NOTHING RETURNING a",
            "INSERT INTO t (a, n) SELECT a, n FROM x ON CONFLICT (a) DO UPDATE SET n = n + EXCLUDED.n USING OPERATION_ID 'op1'",
        ] {
            let ParsedInsertTokens::Select(shape) = parse_insert_any(sql, mode).expect(sql) else {
                panic!("expected Select shape: {sql}");
            };
            assert!(shape.on_conflict.is_some(), "{sql}");
        }
        let ParsedInsertTokens::Select(shape) =
            parse_insert_any("INSERT INTO t (a) SELECT a FROM x", mode).expect("parse")
        else {
            panic!("expected Select shape");
        };
        assert!(shape.on_conflict.is_none());
    }

    // 対象ビヘイビア: SQL-51（ポインタ）。列リスト省略（括弧付き問い合わせを含む）は
    // 省略印付きで受理され、束縛段が展開する（Issue #2613）。
    #[test]
    fn insert_select_accepts_omitted_column_list() {
        let mode = LedgerMode::CompareOnlyWithoutLedger;
        for sql in [
            "INSERT INTO t SELECT a FROM x LIMIT 1",
            "INSERT INTO t (SELECT a FROM x LIMIT 1)",
            "INSERT INTO t SELECT a FROM x LIMIT 1 USING OPERATION_ID 'op-1'",
        ] {
            let ParsedInsertTokens::Select(shape) = parse_insert_any(sql, mode).expect("parse")
            else {
                panic!("expected Select shape: {sql}");
            };
            assert!(shape.columns_omitted, "{sql}");
            assert!(shape.columns.is_empty(), "{sql}");
        }
        let ParsedInsertTokens::Select(shape) =
            parse_insert_any("INSERT INTO t (a) SELECT a FROM x LIMIT 1", mode).expect("parse")
        else {
            panic!("expected Select shape");
        };
        assert!(!shape.columns_omitted);
    }

    #[test]
    fn insert_select_rejections() {
        let mode = LedgerMode::CompareOnlyWithoutLedger;
        let code = |sql: &str| {
            parse_insert_any(sql, mode)
                .expect_err("must fail")
                .wire_code()
                .to_string()
        };
        // 未対応の ON CONFLICT 形は従来どおり fail-closed（Issue #2614）。
        assert_eq!(
            code("INSERT INTO t (a) SELECT a FROM x LIMIT 1 ON CONFLICT DO UPDATE SET a = EXCLUDED.a"),
            "42601"
        );
        // `USING OPERATION_ID` の後ろの `ON CONFLICT` は句順違反。
        assert_eq!(
            code("INSERT INTO t (a) SELECT a FROM x LIMIT 1 USING OPERATION_ID 'op1' ON CONFLICT (a) DO NOTHING"),
            "42601"
        );
        assert_eq!(code("INSERT INTO t (a) RETURNING a"), "42601");
        // `DEFAULT VALUES` の後ろに問い合わせは書けない（列リスト省略は別。Issue #2613）。
        assert_eq!(
            code("INSERT INTO t DEFAULT VALUES SELECT a FROM x LIMIT 1"),
            "42601"
        );
        // 括弧の外の余剰句（`RETURNING` の後ろの `SELECT`）は後続句の解析が `42601` で拒否する。
        assert_eq!(
            code("INSERT INTO t (a) SELECT a FROM x LIMIT 1 RETURNING a SELECT 1"),
            "42601"
        );
        // 必須化ガードはカタログ照会の前（`23502`）
        assert_eq!(
            parse_insert_any(
                "INSERT INTO t (a) SELECT a FROM x LIMIT 1",
                LedgerMode::Ledgered
            )
            .expect_err("must fail")
            .wire_code(),
            "23502"
        );
    }

    #[test]
    fn validate_insert_rejects_select_form_with_0a000() {
        let lookup = catalog_with(&["t", "x"]);
        let err = validate_insert(
            "INSERT INTO t (a) SELECT a FROM x LIMIT 1",
            &lookup,
            LedgerMode::CompareOnlyWithoutLedger,
        )
        .expect_err("SELECT form is not supported on this entry point");
        assert_eq!(err.wire_code(), "0A000");
    }

    #[test]
    fn validate_insert_default_has_no_row_count_cap() {
        // Issue #997・オーナー判断の改訂（2026-09-27、汎用 RDB との整合）:
        // `validate_insert`（`max_insert_rows` 未指定＝`None`）は既定で上限を
        // 持たないため、旧既定値（`MAX_INSERT_ROWS_PER_STATEMENT`＝1,000）を
        // 超える行数でも構造検証段では拒否されない（BREAKING CHANGE の外部
        // 観測）。`tests/insert_multi_row.rs` の結合テストは定数値へ依存せず
        // 「明らかに超過する規模」を使う方針のため、境界値ちょうどの検証は
        // 本ユニットテストが担う。
        let lookup = catalog_with(&["documents"]);
        let rows: Vec<String> = (0..MAX_INSERT_ROWS_PER_STATEMENT + 1)
            .map(|i| format!("({i})"))
            .collect();
        let sql = format!(
            "INSERT INTO documents (id) VALUES {} USING OPERATION_ID 'op-0001'",
            rows.join(", ")
        );
        let stmt = validate_insert(&sql, &lookup, LedgerMode::Ledgered)
            .expect("no default row count cap must accept rows beyond the old default");
        assert_eq!(stmt.rows.len(), MAX_INSERT_ROWS_PER_STATEMENT + 1);
    }

    #[test]
    fn accepts_insert_at_configured_max_row_count_boundary() {
        // SQL-16・TASK-190: `--max-insert-rows` で明示指定した上限ちょうどの
        // 行数は受理される（境界値検証）。
        let lookup = catalog_with(&["documents"]);
        let limit = std::num::NonZeroUsize::new(MAX_INSERT_ROWS_PER_STATEMENT)
            .expect("MAX_INSERT_ROWS_PER_STATEMENT is nonzero");
        let rows: Vec<String> = (0..MAX_INSERT_ROWS_PER_STATEMENT)
            .map(|i| format!("({i})"))
            .collect();
        let sql = format!(
            "INSERT INTO documents (id) VALUES {} USING OPERATION_ID 'op-0001'",
            rows.join(", ")
        );
        let stmt = validate_insert_with_limit(&sql, &lookup, LedgerMode::Ledgered, Some(limit))
            .expect("row count at the configured limit must be accepted");
        assert_eq!(stmt.rows.len(), MAX_INSERT_ROWS_PER_STATEMENT);
    }

    #[test]
    fn rejects_insert_exceeding_configured_max_row_count_before_catalog_lookup() {
        // SQL-16・TASK-190: `--max-insert-rows` で明示指定した上限を 1 行超えると
        // `54000` で拒否され、かつ判定は行を積む最中（構造検証段階）に完結する
        // ため `TableLookup::table_exists` へは一切到達しない（副作用ゼロの
        // 根拠。`explicit_null_operation_id_does_not_reach_catalog_lookup` と
        // 同じ `FlaggingCatalog` パターン）。
        struct FlaggingCatalog {
            called: std::cell::Cell<bool>,
        }
        impl TableLookup for FlaggingCatalog {
            fn table_exists(&self, _name: &str) -> Result<bool, SqlSurfaceError> {
                self.called.set(true);
                Ok(true)
            }
        }
        let lookup = FlaggingCatalog {
            called: std::cell::Cell::new(false),
        };
        let limit = std::num::NonZeroUsize::new(MAX_INSERT_ROWS_PER_STATEMENT)
            .expect("MAX_INSERT_ROWS_PER_STATEMENT is nonzero");
        let rows: Vec<String> = (0..MAX_INSERT_ROWS_PER_STATEMENT + 1)
            .map(|i| format!("({i})"))
            .collect();
        let sql = format!(
            "INSERT INTO documents (id) VALUES {} USING OPERATION_ID 'op-0001'",
            rows.join(", ")
        );
        let err = validate_insert_with_limit(&sql, &lookup, LedgerMode::Ledgered, Some(limit))
            .expect_err("must be rejected");
        assert_eq!(err.wire_code(), "54000");
        assert!(
            !lookup.called.get(),
            "row count limit must be rejected before the catalog lookup"
        );
    }

    #[test]
    fn same_insert_input_yields_same_classification_across_repeated_calls() {
        let lookup = catalog_with(&["documents"]);
        let sql = "INSERT INTO documents (id) VALUES (1)";
        let first = validate_insert(sql, &lookup, LedgerMode::Ledgered)
            .unwrap_err()
            .wire_code();
        let second = validate_insert(sql, &lookup, LedgerMode::Ledgered)
            .unwrap_err()
            .wire_code();
        assert_eq!(first, second);
    }

