    fn truncate_names(
        sql: &str,
        tables: &'static [&'static str],
    ) -> Result<Vec<String>, SqlSurfaceError> {
        let lookup = catalog_with(tables);
        validate_truncate(sql, &lookup, LedgerMode::Ledgered).map(|v| v.table_names)
    }

