    /// SQL-48 (3): 識別句は表リスト直後・CASCADE／RESTRICT の手前に置け、既定は CONTINUE。
    #[test]
    fn accepts_truncate_identity_clause() {
        let lookup = catalog_with(&["a", "b"]);
        let op = "USING OPERATION_ID 'op-0001'";
        for (sql, restart, behavior) in [
            (format!("TRUNCATE a {op}"), false, DropBehavior::Restrict),
            (
                format!("TRUNCATE a restart identity {op}"),
                true,
                DropBehavior::Restrict,
            ),
            (
                format!("TRUNCATE a CONTINUE IDENTITY {op}"),
                false,
                DropBehavior::Restrict,
            ),
            (
                format!("TRUNCATE a, b RESTART IDENTITY CASCADE {op}"),
                true,
                DropBehavior::Cascade,
            ),
            (
                format!("TRUNCATE a CONTINUE IDENTITY RESTRICT {op}"),
                false,
                DropBehavior::Restrict,
            ),
        ] {
            let v = validate_truncate(&sql, &lookup, LedgerMode::Ledgered).expect(&sql);
            assert_eq!(v.restart_identity, restart, "{sql}");
            assert_eq!(v.behavior, behavior, "{sql}");
        }
    }

    /// `restart` という名前の表は従来どおり表名として扱われる。
    #[test]
    fn truncate_restart_named_table_is_still_a_table_name() {
        let lookup = catalog_with(&["restart"]);
        let v = validate_truncate(
            "TRUNCATE restart USING OPERATION_ID 'op-0001'",
            &lookup,
            LedgerMode::Ledgered,
        )
        .expect("table named restart");
        assert_eq!(v.table_names, vec!["restart".to_string()]);
        assert!(!v.restart_identity);
    }

    fn truncate_behavior(sql: &str, tables: &[&'static str]) -> (DropBehavior, Vec<String>) {
        let lookup = catalog_with(tables);
        let v = validate_truncate(sql, &lookup, LedgerMode::Ledgered).expect(sql);
        (v.behavior, v.table_names)
    }

    /// SQL-48 (2): `CASCADE`／`RESTRICT` は表リスト直後に 1 つだけ書け、省略時は RESTRICT。
    #[test]
    fn accepts_truncate_cascade_and_restrict_with_default_restrict() {
        let op = "USING OPERATION_ID 'op-0001'";
        assert_eq!(
            truncate_behavior(&format!("TRUNCATE a {op}"), &["a"]).0,
            DropBehavior::Restrict
        );
        assert_eq!(
            truncate_behavior(&format!("TRUNCATE a RESTRICT {op}"), &["a"]).0,
            DropBehavior::Restrict
        );
        let (b, names) =
            truncate_behavior(&format!("TRUNCATE TABLE a, b cascade {op}"), &["a", "b"]);
        assert_eq!(b, DropBehavior::Cascade);
        assert_eq!(names, vec!["a", "b"]);
        // 末尾 `;` と、`only` を表名として使う形。
        assert_eq!(
            truncate_behavior(&format!("TRUNCATE a CASCADE {op};"), &["a"]).0,
            DropBehavior::Cascade
        );
        // 字句上 `ONLY` と引用付き `"only"` は区別できないため、`only` を表名にする
        // 場合は後続を `,`・`*`・`USING OPERATION_ID` にする（`ONLY cascade` は修飾子＋表名）。
        let (b, names) = truncate_behavior(
            &format!("TRUNCATE \"only\", a CASCADE {op}"),
            &["only", "a"],
        );
        assert_eq!(
            (b, names),
            (
                DropBehavior::Cascade,
                vec!["only".to_string(), "a".to_string()]
            )
        );
    }

    /// `cascade` という名前の表は従来どおり表名として扱う（先に `expect_ident` で読むため）。
    #[test]
    fn truncate_cascade_word_can_be_a_table_name() {
        let op = "USING OPERATION_ID 'op-0001'";
        let (b, names) = truncate_behavior(&format!("TRUNCATE cascade {op}"), &["cascade"]);
        assert_eq!(
            (b, names),
            (DropBehavior::Restrict, vec!["cascade".to_string()])
        );
        let (b, names) = truncate_behavior(&format!("TRUNCATE cascade CASCADE {op}"), &["cascade"]);
        assert_eq!(
            (b, names),
            (DropBehavior::Cascade, vec!["cascade".to_string()])
        );
    }

    /// `TABLE`／`ONLY` 修飾子の直後の `cascade`／`restrict` は常に表名（レビュー指摘の回帰）。
    #[test]
    fn truncate_modifier_followed_by_cascade_word_keeps_it_as_table_name() {
        let op = "USING OPERATION_ID 'op-0001'";
        for (sql, name) in [
            (format!("TRUNCATE TABLE cascade {op}"), "cascade"),
            (format!("TRUNCATE ONLY cascade {op}"), "cascade"),
            (format!("TRUNCATE only cascade {op}"), "cascade"),
            // `USING` なし（CompareOnlyWithoutLedger）でも同じ解釈（PostgreSQL 互換）。
            ("TRUNCATE only CASCADE".to_string(), "CASCADE"),
        ] {
            let lookup = catalog_with(&["cascade", "CASCADE"]);
            let v =
                validate_truncate(&sql, &lookup, LedgerMode::CompareOnlyWithoutLedger).expect(&sql);
            assert_eq!(
                (v.behavior, v.table_names),
                (DropBehavior::Restrict, vec![name.to_string()]),
                "{sql}"
            );
        }
        let (b, names) = truncate_behavior(&format!("TRUNCATE TABLE restrict {op}"), &["restrict"]);
        assert_eq!(
            (b, names),
            (DropBehavior::Restrict, vec!["restrict".to_string()])
        );
    }

