    #[test]
    fn using_and_set_remain_usable_as_table_and_column_identifiers() {
        // codex-review P1 の回帰テスト: `USING`／`SET` を字句解析段階で無条件に
        // キーワード化すると、カタログ上有効な識別子（`[A-Za-z_][A-Za-z0-9_]*`）
        // である `using`／`set` というテーブル名・列名が `FROM`・投影・`ORDER BY`
        // などの識別子位置で使えなくなる未告知の破壊的変更になる。`USING`／`SET` が
        // 構文上必須の位置（`LIMIT` 直後・statement 先頭）以外では、従来どおり
        // `Ident` として通ることを確認する。
        let lookup = catalog_with(&["using", "set"]);

        // テーブル名としての `using`／`set`（FROM 句の識別子位置）。
        let stmt = validate_statement(
            "SELECT * FROM using ORDER BY embedding <=> '[0.1]' LIMIT 5",
            &lookup,
        )
        .expect("table named `using` should remain a valid identifier");
        assert_eq!(stmt.table_name, "using");
        let stmt = validate_statement(
            "SELECT * FROM set ORDER BY embedding <=> '[0.1]' LIMIT 5",
            &lookup,
        )
        .expect("table named `set` should remain a valid identifier");
        assert_eq!(stmt.table_name, "set");

        // 投影リストの列名としての `using`／`set`。
        validate_statement(
            "SELECT using, set FROM using ORDER BY embedding <=> '[0.1]' LIMIT 5",
            &lookup,
        )
        .expect("columns named `using`/`set` should remain valid identifiers");
    }

    // --- 集計 SELECT（TASK-166・SQL-13） ------------------------------------

    fn expect_aggregate(sql: &str, lookup: &impl TableLookup) -> ValidatedAggregate {
        match validate_sql(sql, lookup).expect("expected the aggregate shape to be accepted") {
            Statement::Aggregate(agg) => agg,
            other => panic!("expected Statement::Aggregate, got {other:?}"),
        }
    }

    /// [`AggregateSelectItem::Aggregate`] であることを前提に中身を取り出す
    /// （TASK-167・SQL-14 で `items()` の要素型が `AggregateSelectItem` へ変わった
    /// ことに伴うテストヘルパ）。
    fn expect_agg_item(item: &AggregateSelectItem) -> &AggregateItem {
        match item {
            AggregateSelectItem::Aggregate(item) => item,
            AggregateSelectItem::GroupKey { .. } => {
                panic!("expected an aggregate item, got a GroupKey item")
            }
            AggregateSelectItem::Expr { .. } => {
                panic!("expected an aggregate item, got an expression item")
            }
        }
    }

    /// SQL-57・Issue #1800: `string_agg` の構文。2 引数・`DISTINCT`・内側 `ORDER BY`（複数キー・
    /// 方向・`NULLS`）が `AggregateItem` へ載り、式の引数（区切り）も保持される。
    #[test]
    fn string_agg_parses_arguments_distinct_and_inner_order_by() {
        let lookup = catalog_with(&["documents"]);
        let agg = expect_aggregate(
            "SELECT string_agg(DISTINCT a, ',' ORDER BY a DESC NULLS LAST, b), \
             STRING_AGG(a, b) AS names FROM documents",
            &lookup,
        );
        let first = expect_agg_item(&agg.items()[0]);
        assert_eq!(first.func, AggregateFunc::StringAgg);
        assert!(first.distinct);
        assert_eq!(first.extra_args.len(), 1);
        assert_eq!(first.order_by.len(), 2);
        assert!(first.order_by[0].descending);
        assert_eq!(first.order_by[0].nulls, Some(NullPlacement::Last));
        assert!(!first.order_by[1].descending);
        assert_eq!(first.order_by[1].nulls, None);
        let second = expect_agg_item(&agg.items()[1]);
        assert!(!second.distinct);
        assert!(second.order_by.is_empty());
        assert_eq!(second.alias.as_deref(), Some("names"));
        assert_eq!(second.func.default_alias(), "string_agg");
    }

    /// PR #2671 レビュー対応: `DISTINCT` 直後の文字列リテラル・括弧式を修飾子と判定し、
    /// 裸の `NULL` は引数と内側 `ORDER BY` で同じリテラルとして解析される。
    #[test]
    fn string_agg_distinct_modifier_before_literal_paren_and_null_order_key() {
        let lookup = catalog_with(&["documents"]);
        for sql in [
            "SELECT string_agg(DISTINCT 'x', ',') FROM documents",
            "SELECT string_agg(DISTINCT ('x'), ',') FROM documents",
        ] {
            let agg = expect_aggregate(sql, &lookup);
            assert!(expect_agg_item(&agg.items()[0]).distinct, "{sql}");
        }
        let agg = expect_aggregate(
            "SELECT string_agg(DISTINCT NULL, ',' ORDER BY NULL) FROM documents",
            &lookup,
        );
        let item = expect_agg_item(&agg.items()[0]);
        assert!(item.distinct);
        assert_eq!(item.order_by.len(), 1);
        assert_eq!(
            format!("{:?}", item.order_by[0].expr),
            format!(
                "{:?}",
                match &item.arg {
                    AggregateArg::Expr(e) => e,
                    _ => panic!("expr arg expected"),
                }
            )
        );
        // 列名 `distinct` を引数に取る既存形は維持する。
        let agg = expect_aggregate("SELECT string_agg(distinct, ',') FROM documents", &lookup);
        assert!(!expect_agg_item(&agg.items()[0]).distinct);
    }

    /// SQL-57: 引数の個数違いは `42883`、`*` は `42601`、キー数の超過は確保前に `54000`、
    /// 他の集計へは 2 引数・内側 `ORDER BY`・`DISTINCT` を広げない（`42601`）。JOIN は `0A000`。
    #[test]
    fn string_agg_rejects_malformed_shapes_fail_closed() {
        let lookup = catalog_with(&["documents"]);
        let code = |sql: &str| validate_sql(sql, &lookup).expect_err(sql).wire_code();
        assert_eq!(code("SELECT string_agg(a) FROM documents"), "42883");
        assert_eq!(
            code("SELECT string_agg(a, ',', ',') FROM documents"),
            "42883"
        );
        assert_eq!(code("SELECT string_agg() FROM documents"), "42601");
        assert_eq!(code("SELECT string_agg(*) FROM documents"), "42601");
        assert_eq!(code("SELECT sum(a, b) FROM documents"), "42601");
        assert_eq!(code("SELECT count(a ORDER BY a) FROM documents"), "42601");
        assert_eq!(code("SELECT sum(DISTINCT a) FROM documents"), "42601");
        let keys = ["a"; MAX_SCALAR_ORDER_KEYS + 1].join(", ");
        assert_eq!(
            code(&format!(
                "SELECT string_agg(a, ',' ORDER BY {keys}) FROM documents"
            )),
            "54000"
        );
        assert!(is_aggregate_function_name("String_Agg"));
    }
    /// SQL-57・Issue #1801: `array_agg` の構文。1 引数・`DISTINCT`・内側 `ORDER BY`（複数キー・
    /// 方向・NULL 位置）が AST に載り、数値リテラル・括弧式の前の `DISTINCT` も修飾子と読まれる。
    #[test]
    fn array_agg_parses_distinct_and_inner_order_by() {
        let lookup = catalog_with(&["documents"]);
        let agg = expect_aggregate(
            "SELECT array_agg(DISTINCT a ORDER BY a DESC NULLS LAST), ARRAY_AGG(b) AS xs, \
             array_agg(DISTINCT 1), array_agg(DISTINCT ('x')) FROM documents",
            &lookup,
        );
        let first = expect_agg_item(&agg.items()[0]);
        assert_eq!(first.func, AggregateFunc::ArrayAgg);
        assert!(first.distinct);
        assert!(first.extra_args.is_empty());
        assert_eq!(first.order_by.len(), 1);
        assert!(first.order_by[0].descending);
        assert_eq!(first.order_by[0].nulls, Some(NullPlacement::Last));
        let second = expect_agg_item(&agg.items()[1]);
        assert!(!second.distinct);
        assert!(second.order_by.is_empty());
        assert_eq!(second.alias.as_deref(), Some("xs"));
        assert_eq!(second.func.default_alias(), "array_agg");
        assert!(expect_agg_item(&agg.items()[2]).distinct);
        assert!(expect_agg_item(&agg.items()[3]).distinct);
        // 列名 `distinct` を引数に取る形は維持する。
        let agg = expect_aggregate("SELECT array_agg(distinct) FROM documents", &lookup);
        assert!(!expect_agg_item(&agg.items()[0]).distinct);
    }

    /// SQL-57・Issue #1809: 集計引数の単項マイナスと `COUNT(DISTINCT (式))`・`COUNT(DISTINCT -式)`。
    /// `COUNT(distinct)` の列名読みと、入れ子集計の `42601` は維持する。
    #[test]
    fn aggregate_arguments_accept_unary_minus_and_distinct_before_paren() {
        let lookup = catalog_with(&["documents"]);
        let agg = expect_aggregate(
            "SELECT sum(-a), sum(abs(-a)), count(DISTINCT (a + b)), count(DISTINCT -a), \
             count(distinct), count(a - b) FROM documents",
            &lookup,
        );
        let item = |i: usize| expect_agg_item(&agg.items()[i]);
        assert!(!item(0).distinct && !item(1).distinct);
        assert!(item(2).distinct && item(3).distinct);
        assert!(!item(4).distinct);
        assert!(matches!(item(4).arg, AggregateArg::Expr(Expr::Ident(_))));
        assert!(!item(5).distinct);
        let err = validate_sql("SELECT sum(count(*)) FROM documents", &lookup)
            .expect_err("nested aggregate must be rejected");
        assert_eq!(err.wire_code(), "42601");
    }

    /// SQL-57・Issue #1805: `bool_and` 系の構文。既定別名・比較式の引数が AST に載り、
    /// 2 引数は `42883`、`DISTINCT`・内側 `ORDER BY`・論理演算の引数は `42601`。
    #[test]
    fn bool_aggregates_parse_comparison_arguments() {
        let lookup = catalog_with(&["documents"]);
        let agg = expect_aggregate(
            "SELECT bool_and(a), BOOL_OR(a > 1), every(a = b) AS e FROM documents",
            &lookup,
        );
        let first = expect_agg_item(&agg.items()[0]);
        assert_eq!(first.func, AggregateFunc::BoolAnd);
        assert!(matches!(first.arg, AggregateArg::Expr(Expr::Ident(_))));
        let second = expect_agg_item(&agg.items()[1]);
        assert_eq!(second.func, AggregateFunc::BoolOr);
        assert!(matches!(
            second.arg,
            AggregateArg::Expr(Expr::Binary { op: BinOp::Gt, .. })
        ));
        let third = expect_agg_item(&agg.items()[2]);
        assert_eq!(third.func, AggregateFunc::Every);
        assert_eq!(third.func.default_alias(), "every");
        assert_eq!(third.alias.as_deref(), Some("e"));
        let code = |sql: &str| validate_sql(sql, &lookup).expect_err(sql).wire_code();
        assert_eq!(code("SELECT bool_and(a, b) FROM documents"), "42883");
        assert_eq!(code("SELECT bool_and(DISTINCT a) FROM documents"), "42601");
        assert_eq!(
            code("SELECT bool_and(a ORDER BY a) FROM documents"),
            "42601"
        );
        assert!(is_aggregate_function_name("Every"));
    }

    /// SQL-57・Issue #1801: 引数の個数違いは `42883`（2 引数以上）・`42601`（0 引数・`*`）、
    /// キー数の超過は確保前に `54000`。他の集計へ内側 `ORDER BY`・`DISTINCT` を広げない。
    #[test]
    fn array_agg_rejects_malformed_shapes_fail_closed() {
        let lookup = catalog_with(&["documents"]);
        let code = |sql: &str| validate_sql(sql, &lookup).expect_err(sql).wire_code();
        assert_eq!(code("SELECT array_agg(a, b) FROM documents"), "42883");
        assert_eq!(code("SELECT array_agg() FROM documents"), "42601");
        assert_eq!(code("SELECT array_agg(*) FROM documents"), "42601");
        assert_eq!(code("SELECT min(a ORDER BY a) FROM documents"), "42601");
        let keys = ["a"; MAX_SCALAR_ORDER_KEYS + 1].join(", ");
        assert_eq!(
            code(&format!(
                "SELECT array_agg(a ORDER BY {keys}) FROM documents"
            )),
            "54000"
        );
        assert!(is_aggregate_function_name("Array_Agg"));
    }

    /// SQL-57・Issue #1806: `FILTER (WHERE ...)` の構文。AND 結合・OR・部分クエリを受理し、
    /// 集計式項目の中の集計・`DISTINCT`・内側 `ORDER BY` との併用でも AST に載る。
    #[test]
    fn aggregate_filter_parses_conditions_into_the_ast() {
        let lookup = catalog_with(&["documents"]);
        let agg = expect_aggregate(
            "SELECT count(*) FILTER (WHERE a = 'x' AND n > 1), \
             sum(n) FILTER (WHERE a = 'y' OR a = 'z') AS s, \
             count(DISTINCT a) FILTER (WHERE n IS NULL), count(*), \
             string_agg(a, ',' ORDER BY a) FILTER (WHERE flag) \
             FROM documents",
            &lookup,
        );
        assert_eq!(expect_agg_item(&agg.items()[0]).filter.len(), 2);
        assert!(matches!(
            expect_agg_item(&agg.items()[1]).filter.as_slice(),
            [WherePredicate::Or(_)]
        ));
        assert_eq!(expect_agg_item(&agg.items()[2]).filter.len(), 1);
        assert!(expect_agg_item(&agg.items()[3]).filter.is_empty());
        assert_eq!(expect_agg_item(&agg.items()[4]).filter.len(), 1);
        // 集計式項目の中の集計にも FILTER が付く。
        let agg = expect_aggregate(
            "SELECT sum(n) FILTER (WHERE a = 'x') + 1 FROM documents",
            &lookup,
        );
        match &agg.items()[0] {
            AggregateSelectItem::Expr { aggregates, .. } => {
                assert_eq!(aggregates.len(), 1);
                assert_eq!(aggregates[0].filter.len(), 1);
            }
            other => panic!("expected an expression item, got {other:?}"),
        }
        // FILTER 内の部分クエリは構文段では受理する（解決は実行段）。
        let tokens = super::super::relation_name::tokenize_resolved(
            "SELECT count(*) FILTER (WHERE a IN (SELECT a FROM documents LIMIT 5)) FROM documents",
            false,
        )
        .expect("tokenize");
        let Statement::Aggregate(agg) =
            validate_sql_tokens_with_subquery_ctx(&tokens, &lookup, 0).expect("subquery in FILTER")
        else {
            panic!("expected Statement::Aggregate");
        };
        assert!(matches!(
            expect_agg_item(&agg.items()[0]).filter.as_slice(),
            [WherePredicate::InSubquery { .. }]
        ));
    }

    /// SQL-57・Issue #1806: FILTER の誤形は fail-closed。条件中の集計は `42803`、ウィンドウは
    /// `42P20`（OVER を集計より優先）、`$n` と `WHERE` の欠落は `42601`。部分クエリ内の集計は合法。
    #[test]
    fn aggregate_filter_rejects_malformed_and_forbidden_shapes() {
        let lookup = catalog_with(&["documents"]);
        let code = |sql: &str| validate_sql(sql, &lookup).expect_err(sql).wire_code();
        assert_eq!(
            code("SELECT count(*) FILTER (WHERE count(*) > 1) FROM documents"),
            "42803"
        );
        assert_eq!(
            code("SELECT count(*) FILTER (WHERE n > (1 + max(n))) FROM documents"),
            "42803"
        );
        assert_eq!(
            code("SELECT count(*) FILTER (WHERE sum(n) OVER () > 1) FROM documents"),
            "42P20"
        );
        assert_eq!(
            code("SELECT count(*) FILTER (WHERE row_number() OVER () > 1) FROM documents"),
            "42P20"
        );
        assert_eq!(
            code("SELECT count(*) FILTER (a = 'x') FROM documents"),
            "42601"
        );
        assert_eq!(
            code("SELECT count(*) FILTER (WHERE) FROM documents"),
            "42601"
        );
        assert_eq!(
            code("SELECT count(*) FILTER (WHERE a = 'x' FROM documents"),
            "42601"
        );
        assert_eq!(
            code("SELECT count(*) FILTER (WHERE a = 'x') OVER () FROM documents"),
            "42601"
        );
        // 部分クエリの内側の集計は FILTER 内の集計禁止の対象外。
        let tokens = super::super::relation_name::tokenize_resolved(
            "SELECT count(*) FILTER (WHERE n = (SELECT max(n) FROM documents)) FROM documents",
            false,
        )
        .expect("tokenize");
        validate_sql_tokens_with_subquery_ctx(&tokens, &lookup, 0)
            .expect("an aggregate inside a subquery is allowed");
        // 部分クエリを許さない文脈（カーソル・ビュー本体等）では構文段で `42601`。
        assert_eq!(
            code("SELECT count(*) FILTER (WHERE a IN (SELECT a FROM documents LIMIT 5)) FROM documents"),
            "42601"
        );
        // `filter` を列別名として使える（FILTER の直後が `(` でなければ句ではない）。
        let agg = expect_aggregate("SELECT count(*) AS filter FROM documents", &lookup);
        assert!(expect_agg_item(&agg.items()[0]).filter.is_empty());
    }

    /// Issue #1541（SQL-42 (5) のポインタ）: 集計呼び出しの直後の算術演算子で集計式項目になり、
    /// 式中の集計呼び出しは内部名へ置換されて `aggregates` に出現順で抽出される。
    #[test]
    fn aggregate_arithmetic_item_extracts_calls_into_placeholders() {
        let lookup = catalog_with(&["documents"]);
        let agg = expect_aggregate(
            "SELECT sum(n)+1, count(*)*2 AS c, max(a)-min(a) FROM documents",
            &lookup,
        );
        assert_eq!(agg.items().len(), 3);
        match &agg.items()[0] {
            AggregateSelectItem::Expr {
                expr,
                aggregates,
                alias,
            } => {
                assert_eq!(aggregates.len(), 1);
                assert_eq!(aggregates[0].func, AggregateFunc::Sum);
                assert_eq!(*alias, None);
                assert!(matches!(
                    expr,
                    Expr::Binary { op: BinOp::Add, lhs, .. }
                        if matches!(&**lhs, Expr::Ident(n) if aggregate_placeholder_index(n) == Some(0))
                ));
            }
            other => panic!("expected an expression item, got {other:?}"),
        }
        match &agg.items()[1] {
            AggregateSelectItem::Expr { alias, .. } => assert_eq!(alias.as_deref(), Some("c")),
            other => panic!("expected an expression item, got {other:?}"),
        }
        match &agg.items()[2] {
            AggregateSelectItem::Expr { aggregates, .. } => {
                let funcs: Vec<_> = aggregates.iter().map(|a| a.func).collect();
                assert_eq!(funcs, vec![AggregateFunc::Max, AggregateFunc::Min]);
            }
            other => panic!("expected an expression item, got {other:?}"),
        }
    }

    /// 従来形（集計単独・別名付き・`GROUP BY` 列）の AST は集計式項目の追加で変わらない。
    #[test]
    fn aggregate_arithmetic_keeps_plain_item_shapes() {
        let lookup = catalog_with(&["documents"]);
        let agg = expect_aggregate("SELECT sum(n) AS s, count(*) FROM documents", &lookup);
        assert!(agg
            .items()
            .iter()
            .all(|i| matches!(i, AggregateSelectItem::Aggregate(_))));
        assert_eq!(expect_agg_item(&agg.items()[0]).alias.as_deref(), Some("s"));
        let agg = expect_aggregate(
            "SELECT lang, count(*) FROM documents GROUP BY lang",
            &lookup,
        );
        assert!(matches!(
            agg.items()[0],
            AggregateSelectItem::GroupKey { .. }
        ));
    }

    /// 集計式項目でも `GROUP BY` 外の列・`GROUP BY` なしの裸列・入れ子集計は `42601`、
    /// 1 項目への過剰な集計詰め込みは `54000`。内部名は利用者の識別子と衝突しない。
    #[test]
    fn aggregate_arithmetic_rejections_and_limits() {
        let lookup = catalog_with(&["documents"]);
        // Issue #1818・SQL-58: トップレベルは SELECT の列参照と `GROUP BY` の照合（`42803`）を束縛段で
        // 行うため、構文段は受理する（分類は束縛段の結合テストが検証する）。
        for sql in [
            "SELECT sum(n)+m FROM documents",
            "SELECT lang, sum(n)+m FROM documents GROUP BY lang",
        ] {
            validate_sql(sql, &lookup).expect(sql);
        }
        for sql in [
            "SELECT sum(count(*))+1 FROM documents",
            "SELECT lang+lang FROM documents GROUP BY lang",
            "SELECT sum(n)+1 FROM documents WHERE count(*) > 1",
        ] {
            let err = validate_sql(sql, &lookup).expect_err(sql);
            assert_eq!(err.wire_code(), "42601", "{sql}");
        }
        let many = vec!["count(*)"; 40].join("+");
        let err = validate_sql(&format!("SELECT {many} FROM documents"), &lookup)
            .expect_err("too many aggregate calls");
        assert_eq!(err.wire_code(), "54000");
        let lexed = crate::sql::lexer::tokenize("SELECT \"\u{1}agg0\" FROM documents");
        assert!(
            lexed.is_err(),
            "placeholder-like identifiers cannot be written"
        );
    }

