    /// SQL-58（Issue #1815）: `ORDER BY` 内の集計呼び出しは `HAVING` と共有の隠し集計配列へ
    /// 脱糖され、素の呼び出しキーは識別子キー（内部名）へ正規化される。
    #[test]
    fn order_by_aggregate_calls_are_desugared_and_shared_with_having() {
        let lookup = catalog_with(&["documents"]);
        let parse = |sql: &str| match validate_sql(sql, &lookup).expect("must be accepted") {
            Statement::Aggregate(agg) => agg,
            other => panic!("unexpected statement: {other:?}"),
        };
        let agg =
            parse("SELECT lang, COUNT(*) AS c FROM documents GROUP BY lang ORDER BY sum(n) DESC");
        let clause = agg.group_by().expect("clause");
        assert_eq!(clause.order_by[0].target, aggregate_placeholder(0));
        assert!(clause.order_by[0].expr.is_none());
        assert_eq!(clause.having_aggregates.len(), 1);
        let agg = parse(
            "SELECT lang, COUNT(*) AS c FROM documents GROUP BY lang \
             HAVING sum(n) > 1 ORDER BY sum(n)",
        );
        assert_eq!(agg.group_by().expect("clause").having_aggregates.len(), 1);
        let agg = parse(
            "SELECT lang, COUNT(*) AS c FROM documents GROUP BY lang ORDER BY coalesce(max(n), 0)",
        );
        assert!(agg.group_by().expect("clause").order_by[0].expr.is_some());
        parse("SELECT lang FROM documents GROUP BY lang ORDER BY count(*)");
        for sql in [
            "SELECT lang, COUNT(*) FROM documents GROUP BY lang ORDER BY sum(count(*))",
            "SELECT lang FROM documents GROUP BY lang ORDER BY lang",
            "SELECT DISTINCT lang FROM documents ORDER BY count(*)",
            "SELECT COUNT(*) FROM documents ORDER BY count(*)",
        ] {
            let err = validate_sql(sql, &lookup).expect_err(sql);
            assert_eq!(err.wire_code(), "42601", "{sql}");
        }
    }

    /// SQL-58（Issue #1814）: `HAVING` 内の集計呼び出しは内部名へ脱糖され、重複排除される。
    #[test]
    fn having_aggregate_calls_are_desugared_and_deduplicated() {
        let lookup = catalog_with(&["documents"]);
        let parse = |sql: &str| match validate_sql(sql, &lookup).expect("must be accepted") {
            Statement::Aggregate(agg) => agg,
            other => panic!("unexpected statement: {other:?}"),
        };
        let agg = parse(
            "SELECT lang, SUM(n) AS s FROM documents GROUP BY lang \
             HAVING count(*) > 1 AND count(*) < 5 AND coalesce(max(n), 0) > 1",
        );
        let clause = agg.group_by().expect("GROUP BY clause");
        assert_eq!(clause.having.len(), 2);
        assert_eq!(clause.having[0].item_name, aggregate_placeholder(0));
        assert_eq!(clause.having[1].item_name, aggregate_placeholder(0));
        assert_eq!(clause.having_exprs.len(), 1);
        assert_eq!(clause.having_aggregates.len(), 2);
        // SELECT リストに集計項目が無い形も、HAVING が集計を持てば受理する。
        let agg = parse("SELECT lang FROM documents GROUP BY lang HAVING count(*) > 1");
        assert_eq!(agg.group_by().expect("clause").having_aggregates.len(), 1);
        // 列名の `count`（括弧なし）は従来どおり項目名参照。
        let agg =
            parse("SELECT lang, COUNT(*) AS count FROM documents GROUP BY lang HAVING count > 1");
        assert!(agg.group_by().expect("clause").having_aggregates.is_empty());
    }

    #[test]
    fn having_aggregate_calls_reject_unsupported_forms() {
        let lookup = catalog_with(&["documents"]);
        for sql in [
            "SELECT lang FROM documents GROUP BY lang",
            "SELECT lang FROM documents GROUP BY lang HAVING lang = 'ja'",
            "SELECT lang FROM documents GROUP BY lang HAVING sum(count(*)) > 1",
            "SELECT lang, COUNT(*) FROM documents GROUP BY lang HAVING c + 1 > 2",
        ] {
            let err = validate_sql(sql, &lookup).expect_err("must be rejected");
            assert_eq!(err.wire_code(), "42601", "sql={sql:?}");
        }
    }

    /// Issue #1817・SQL-58: `GROUP BY` の式キーは `key_exprs` へ積み、`columns` の当該位置には
    /// 予約内部名が入る。括弧で囲んだだけの列は列キーへ正規化される。
    #[test]
    fn group_by_expression_keys_are_collected_with_placeholders() {
        let lookup = catalog_with(&["documents"]);
        let stmt = validate_sql(
            "SELECT count(*) FROM documents GROUP BY lang, upper(lang), (title), n / 2",
            &lookup,
        )
        .expect("expression keys are accepted");
        let Statement::Aggregate(agg) = stmt else {
            panic!("expected aggregate");
        };
        let gb = agg.group_by().expect("GROUP BY clause");
        assert_eq!(
            gb.columns,
            vec![
                "lang".to_string(),
                group_key_expr_placeholder(0),
                "title".to_string(),
                group_key_expr_placeholder(1),
            ]
        );
        assert_eq!(gb.key_exprs.len(), 2);
        assert_eq!(group_key_expr_placeholder_index(&gb.columns[1]), Some(0));
        assert_eq!(group_key_expr_placeholder_index("lang"), None);
    }

    /// Issue #1817・SQL-58: 式キー内の分類（先読み検査）。`OVER` を含む文は文全体の分類が
    /// 先に走るため、`42P20` は先読み検査の関数を直接検証する。
    #[test]
    fn group_by_key_precheck_classifies_aggregates_windows_and_params() {
        let check = |sql: &str| {
            let tokens = lexer::tokenize_with_params(sql).expect("tokenize");
            precheck_group_key_tokens(&tokens, 0, tokens.len())
                .expect_err(sql)
                .wire_code()
        };
        assert_eq!(check("count(*)"), "42803");
        assert_eq!(check("n + sum(n)"), "42803");
        assert_eq!(check("row_number() OVER ()"), "42P20");
        assert_eq!(check("sum(n) OVER ()"), "42P20");
        assert_eq!(check("n + $1"), "42601");
        assert_eq!(check("n + (SELECT 1)"), "0A000");
        let ok = lexer::tokenize("upper(lang) || 'x'").expect("tokenize");
        assert!(precheck_group_key_tokens(&ok, 0, ok.len()).is_ok());
    }

    /// Issue #1817・SQL-58: 式キーはトップレベルの集計 `SELECT` だけが受理する。位置指定・
    /// 重複・キー数超過・式が境界まで届かない形は拒否する（fail-closed）。
    #[test]
    fn group_by_expression_keys_reject_unsupported_forms() {
        let lookup = catalog_with(&["documents"]);
        for (sql, code) in [
            ("SELECT count(*) FROM documents GROUP BY 1", "42601"),
            (
                "SELECT count(*) FROM documents GROUP BY n / 2, n / 2",
                "42601",
            ),
            (
                "SELECT count(*) FROM documents GROUP BY lang, (lang)",
                "42601",
            ),
            ("SELECT count(*) FROM documents GROUP BY n / 2 n", "42601"),
            ("SELECT count(*) FROM documents GROUP BY ", "42601"),
            (
                "SELECT count(*) FROM documents GROUP BY a, b, c, d, e, f, g, h, i + 1",
                "54000",
            ),
            // Issue #1818: 集計呼び出しを持たない SELECT は従来どおり拒否する（式キーでも同じ）。
            (
                "SELECT upper(lang) FROM documents GROUP BY upper(lang)",
                "42601",
            ),
        ] {
            let err = validate_sql(sql, &lookup).expect_err(sql);
            assert_eq!(err.wire_code(), code, "{sql}");
        }
        // Issue #1818: 式の SELECT 項目は構文段で受理し、式キーとの構造一致は束縛段が判定する。
        validate_sql(
            "SELECT upper(lang), count(*) FROM documents GROUP BY upper(lang)",
            &lookup,
        )
        .expect("expression select item is accepted at the syntax layer");
    }

    /// Issue #1819・SQL-58 (4): `GROUP BY` なしの `HAVING` は、キー 0 個の `GroupByClause` で受理する。
    #[test]
    fn accepts_having_without_group_by_as_a_zero_key_clause() {
        let lookup = catalog_with(&["documents"]);
        let parse = |sql: &str| match validate_sql(sql, &lookup).expect("must be accepted") {
            Statement::Aggregate(a) => a,
            other => panic!("expected aggregate, got {other:?}"),
        };
        let agg = parse("SELECT COUNT(*) FROM documents HAVING COUNT(*) > 1");
        let clause = agg.group_by().expect("zero-key clause");
        assert!(clause.columns.is_empty());
        assert_eq!(clause.having.len(), 1);
        assert_eq!(clause.having_aggregates.len(), 1);
        assert!(clause.order_by.is_empty() && clause.limit.is_none() && clause.offset == 0);
        // 集計を含まない HAVING・TRUE/FALSE/NULL の畳み込み。
        let agg = parse("SELECT COUNT(*) FROM documents HAVING 1 = 1 AND TRUE AND FALSE AND NULL");
        let clause = agg.group_by().expect("zero-key clause");
        assert_eq!(clause.having_exprs.len(), 4);
        // SELECT リストに集計が無くても、HAVING が集計を持てば構文段は受理する
        // （裸の列の分類は束縛段の `42803`）。
        let agg = parse("SELECT lang FROM documents HAVING count(*) > 1");
        assert_eq!(agg.group_by().expect("clause").having_aggregates.len(), 1);
    }

    /// Issue #1821・SQL-59: `ROLLUP`・`CUBE`・`GROUPING SETS`・複合指定を構文段で受理し、
    /// キーの和集合（`columns`）と展開後のセット列（`grouping_sets`）へ正規化する。
    #[test]
    fn expands_grouping_syntax_into_grouping_sets() {
        let lookup = catalog_with(&["documents"]);
        let clause_of = |gb: &str| {
            let sql = format!("SELECT count(*) FROM documents GROUP BY {gb}");
            match validate_sql(&sql, &lookup).expect(&sql) {
                Statement::Aggregate(a) => a.group_by().expect("clause").clone(),
                other => panic!("expected aggregate, got {other:?}"),
            }
        };
        let c = clause_of("ROLLUP(a, b)");
        assert_eq!(c.columns, vec!["a", "b"]);
        assert_eq!(c.grouping_sets, Some(vec![vec![0, 1], vec![0], vec![]]));
        let c = clause_of("a, cube(b, c)");
        assert_eq!(c.columns, vec!["a", "b", "c"]);
        assert_eq!(
            c.grouping_sets,
            Some(vec![vec![0, 1, 2], vec![0, 1], vec![0, 2], vec![0]])
        );
        let c = clause_of("GROUPING SETS ((a, b), (a), ())");
        assert_eq!(c.grouping_sets, Some(vec![vec![0, 1], vec![0], vec![]]));
        let c = clause_of("grouping sets (a, rollup(b), grouping sets (c, ()))");
        assert_eq!(c.columns, vec!["a", "b", "c"]);
        assert_eq!(
            c.grouping_sets,
            Some(vec![vec![0], vec![1], vec![], vec![2], vec![]])
        );
        // 重複参照は一意化して受理する。式キーは和集合へ入る。
        let c = clause_of("ROLLUP(a, a), upper(b)");
        assert_eq!(c.columns.len(), 2);
        assert_eq!(c.key_exprs.len(), 1);
        assert_eq!(c.grouping_sets, Some(vec![vec![0, 1], vec![0, 1], vec![1]]));
        // 重複キーが構文の前後どちらにあっても同じく受理する。
        for gb in ["lang, lang, ROLLUP(kind)", "lang, ROLLUP(kind), lang"] {
            assert!(clause_of(gb).grouping_sets.is_some(), "{gb}");
        }
        // 空のセットのみ。キーは 0 個。
        let c = clause_of("()");
        assert!(c.columns.is_empty());
        assert_eq!(c.grouping_sets, Some(vec![vec![]]));
        // 構文を含まない句は従来どおり。語は予約語化されない。
        for gb in ["rollup", "cube", "grouping", "a, b"] {
            assert_eq!(clause_of(gb).grouping_sets, None, "{gb}");
        }
        assert_eq!(clause_of("rollup").columns, vec!["rollup"]);
    }

    /// Issue #1821・SQL-59: グルーピング構文の拒否と上限の分類（`42601`・`42803`・
    /// `54000`・`54001`・`54011`）。
    #[test]
    fn rejects_malformed_or_over_limit_grouping_syntax() {
        let lookup = catalog_with(&["documents"]);
        let names = |n: usize| {
            (0..n)
                .map(|i| format!("c{i}"))
                .collect::<Vec<_>>()
                .join(", ")
        };
        let cube12_dup = ["a"; 12].join(", ");
        let nested = format!("{}a{}", "GROUPING SETS (".repeat(9), ")".repeat(9));
        for (gb, code) in [
            ("ROLLUP()".to_string(), "42601"),
            ("CUBE()".to_string(), "42601"),
            ("GROUPING SETS ()".to_string(), "42601"),
            ("ROLLUP(a,)".to_string(), "42601"),
            ("ROLLUP(a".to_string(), "42601"),
            ("ROLLUP(CUBE(a))".to_string(), "42601"),
            ("CUBE(a, ())".to_string(), "42601"),
            ("ROLLUP(count(*))".to_string(), "42803"),
            ("ROLLUP($1)".to_string(), "42601"),
            ("ROLLUP(1)".to_string(), "42601"),
            ("ROLLUP((SELECT 1))".to_string(), "0A000"),
            ("(a, b)".to_string(), "42601"),
            ("a, a".to_string(), "42601"),
            ("DISTINCT a".to_string(), "42601"),
            // 上限: CUBE は 13 要素で 54011、4,096 セット超・入れ子超過は 54001、
            // 一意キー 9 個は 54000（判定順は 54011 → 54001 → 54000）。
            (format!("CUBE({})", names(13)), "54011"),
            (format!("CUBE({cube12_dup}), ROLLUP(a)"), "54001"),
            (nested, "54001"),
            (format!("ROLLUP({})", names(9)), "54000"),
            // 9 キーの後に 13 要素の CUBE は 54011 が先（従来形の上限検査に先取りされない）。
            (format!("{}, CUBE({})", names(9), names(13)), "54011"),
        ] {
            let sql = format!("SELECT count(*) FROM documents GROUP BY {gb}");
            let err = validate_sql(&sql, &lookup).expect_err(&sql);
            assert_eq!(err.wire_code(), code, "{sql}");
        }
        // ちょうど 4,096 セットは受理する。
        let sql = format!("SELECT count(*) FROM documents GROUP BY CUBE({cube12_dup})");
        validate_sql(&sql, &lookup).expect("4096 sets");
    }

    /// Issue #1821: トップレベルの集計 `SELECT` 以外（サブクエリ・CTE 主クエリ・集合演算の枝）
    /// ではグルーピング構文を `42601` で拒否する。
    #[test]
    fn rejects_grouping_syntax_outside_top_level_aggregate_select() {
        let lookup = catalog_with(&["documents"]);
        for sql in [
            "SELECT id FROM documents WHERE id IN (SELECT id FROM documents GROUP BY ROLLUP(lang))",
            "WITH c AS (SELECT 1 FROM documents) SELECT count(*) FROM documents GROUP BY ROLLUP(lang)",
            "SELECT count(*) FROM documents GROUP BY lang UNION SELECT count(*) FROM documents GROUP BY ROLLUP(lang)",
        ] {
            let err = validate_sql(sql, &lookup).expect_err(sql);
            assert_eq!(err.wire_code(), "42601", "{sql}");
        }
    }
    /// Issue #1819: `GROUP BY` なしの `HAVING` を受理するのはトップレベルの集計 `SELECT` だけ。
    /// 後続の `ORDER BY`／`LIMIT`／`OFFSET`・`OR`・CTE 主クエリ・集合演算の枝・ウィンドウ併用は
    /// 従来どおり `42601`。`GROUP BY` も `HAVING` も無い裸の列は `42601` のまま。
    #[test]
    fn having_without_group_by_rejects_unsupported_contexts() {
        let lookup = catalog_with(&["documents"]);
        for sql in [
            "SELECT COUNT(*) FROM documents HAVING COUNT(*) > 1 ORDER BY 1",
            "SELECT COUNT(*) FROM documents HAVING COUNT(*) > 1 LIMIT 1",
            "SELECT COUNT(*) FROM documents HAVING COUNT(*) > 1 OFFSET 1",
            "SELECT COUNT(*) FROM documents HAVING COUNT(*) > 1 OR COUNT(*) < 0",
            "SELECT COUNT(*) OVER () FROM documents HAVING COUNT(*) > 1",
            "SELECT COUNT(*) FROM documents HAVING COUNT(*) > $1",
            "WITH x AS (SELECT lang FROM documents) SELECT COUNT(*) FROM x HAVING COUNT(*) > 1",
            "SELECT COUNT(*) FROM documents HAVING COUNT(*) > 1 UNION ALL SELECT COUNT(*) FROM documents",
        ] {
            let err = validate_sql(sql, &lookup).expect_err("must be rejected");
            assert_eq!(err.wire_code(), "42601", "sql={sql:?}");
        }
    }

    /// Issue #1819: 句としての `HAVING` の判定。引用識別子 `"having"`（列名・別名・表名・比較の
    /// 右辺）とサブクエリ内の `HAVING` は、トップレベルの句とみなさない。
    #[test]
    fn has_top_level_having_clause_distinguishes_quoted_identifiers() {
        let toks = |sql: &str| lexer::tokenize(sql).expect("tokenize");
        for sql in [
            "SELECT COUNT(*) FROM t HAVING COUNT(*) > 1",
            "SELECT lang FROM t HAVING 1 = 1",
            "SELECT COUNT(*) FROM t WHERE a = 1 HAVING (COUNT(*) > 1)",
            "SELECT COUNT(*) FROM t HAVING -1 < COUNT(*)",
        ] {
            assert!(has_top_level_having_clause(&toks(sql)), "{sql}");
        }
        for sql in [
            "SELECT \"having\" FROM t LIMIT 5",
            "SELECT a AS \"having\" FROM t LIMIT 5",
            "SELECT a \"having\" FROM t LIMIT 5",
            "SELECT a, \"having\" FROM t LIMIT 5",
            "SELECT a FROM t WHERE x = \"having\" LIMIT 5",
            "SELECT a FROM t \"having\" WHERE x = 1 LIMIT 5",
            "SELECT a FROM t ORDER BY \"having\" LIMIT 5",
            "SELECT a FROM t WHERE n IN (SELECT n FROM u GROUP BY n HAVING COUNT(*) > 1)",
        ] {
            assert!(!has_top_level_having_clause(&toks(sql)), "{sql}");
        }
    }

